--[[
    VEYL Control — single-file build (generated by tools/bundle.py; do not edit).
    Edit the files in src/ and rebuild. Prefer loader.lua when HttpGet and loadstring exist.
    This file also runs as a LocalScript in StarterPlayer > StarterPlayerScripts.
]]

local MODULES = {}
MODULES[#MODULES + 1] = { path = "src/core.lua", factory = (function()
-- VEYL module: core
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    ----------------------------------------------------------------------------
    -- 1. Services and bootstrap
    ----------------------------------------------------------------------------

    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local Lighting = game:GetService("Lighting")
    local SoundService = game:GetService("SoundService")
    local TeleportService = game:GetService("TeleportService")
    local CollectionService = game:GetService("CollectionService")
    local HttpService = game:GetService("HttpService")
    local MarketplaceService = game:GetService("MarketplaceService")
    local ContentProvider = game:GetService("ContentProvider")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local StarterPack = game:GetService("StarterPack")
    local Stats = game:GetService("Stats")
    local Workspace = game:GetService("Workspace")

    if not RunService:IsClient() then
        error("VEYL Control is a client runtime and cannot run on the server.", 0)
    end
    if not game:IsLoaded() then
        game.Loaded:Wait()
    end

    local LocalPlayer = Players.LocalPlayer
    while not LocalPlayer do
        Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
        LocalPlayer = Players.LocalPlayer
    end
    local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui", 15)

    ----------------------------------------------------------------------------
    -- 2. Configuration and constants
    ----------------------------------------------------------------------------

    local VERSION = "2.0.0"

    local NAMES = {
        gui = "VEYLControl",
        overlay = "VEYLOverlay",
        fx = "VEYLClientFX",
        blur = "VEYLClientBlur",
        colorCorrection = "VEYLColorCorrection",
        bloom = "VEYLBloom",
        atmosphere = "VEYLAtmosphere",
        sound = "VEYLMusicPlayer",
        aimStep = "VEYLAimLab",
        tag = "VEYLTestTarget",
        targetLabel = "VEYLTargetName",
        owned = "VEYLOwned",
    }

    -- Instances left by earlier builds. Each entry is matched by exact name AND class.
    local LEGACY_INSTANCES = {
        { name = "NovaAdminConsole", class = "ScreenGui", where = "gui" },
        { name = "NovaOverlay", class = "ScreenGui", where = "gui" },
        { name = "NovaClientFX", class = "Folder", where = "workspace" },
        { name = "VEYLControl", class = "ScreenGui", where = "gui" },
        { name = "VEYLOverlay", class = "ScreenGui", where = "gui" },
        { name = "VEYLClientFX", class = "Folder", where = "workspace" },
        { name = "VEYLClientBlur", class = "BlurEffect", where = "lighting" },
        { name = "VEYLLocalColorCorrection", class = "ColorCorrectionEffect", where = "lighting" },
        { name = "VEYLColorCorrection", class = "ColorCorrectionEffect", where = "lighting" },
        { name = "VEYLBloom", class = "BloomEffect", where = "lighting" },
        { name = "VEYLAtmosphere", class = "Atmosphere", where = "lighting" },
        { name = "VEYLMusicPlayer", class = "Sound", where = "sound" },
    }

    local LIMITS = {
        logs = 200,
        logView = 60,
        toasts = 4,
        queue = 200,
        bookmarks = 50,
        npcs = 400,
        tools = 400,
        toolDescendants = 600,
        entityRows = 100,
        toolRows = 100,
        history = 120,
        markers = 20,
        highlights = 30,
        configBytes = 262144,
    }

    ----------------------------------------------------------------------------
    -- Module tables (declared up front so every section can reference them)
    ----------------------------------------------------------------------------

    local Util, Log, Notify, Cap, Settings, Binds, Persist = {}, {}, {}, {}, {}, {}, {}
    local UI, Popup, Overlay, Entities, ESP, Aim, World = {}, {}, {}, {}, {}, {}, {}
    local Weapons, Diag, Music, Rejoin, Features, App = {}, {}, {}, {}, {}, {}

    local Session = {
        alive = true,
        startedAt = os.clock(),
    }

    ----------------------------------------------------------------------------
    -- Utilities
    ----------------------------------------------------------------------------

    function Util.trim(value)
        return (string.gsub(string.gsub(tostring(value or ""), "^%s+", ""), "%s+$", ""))
    end

    function Util.round(value, decimals)
        local factor = 10 ^ (decimals or 0)
        return math.floor(value * factor + 0.5) / factor
    end

    function Util.decimalsForStep(step)
        if not step or step >= 1 then
            return 0
        end
        local text = string.format("%.6f", step):gsub("0+$", "")
        local dot = string.find(text, ".", 1, true)
        return dot and (#text - dot) or 0
    end

    function Util.formatNumber(value, decimals)
        if decimals <= 0 then
            return tostring(math.floor(value + 0.5))
        end
        return string.format("%." .. decimals .. "f", value)
    end

    function Util.toHex(color)
        return string.format(
            "#%02X%02X%02X",
            math.clamp(math.floor(color.R * 255 + 0.5), 0, 255),
            math.clamp(math.floor(color.G * 255 + 0.5), 0, 255),
            math.clamp(math.floor(color.B * 255 + 0.5), 0, 255)
        )
    end

    function Util.fromHex(text)
        if type(text) ~= "string" then
            return nil
        end
        local r, g, b = string.match(Util.trim(text), "^#?(%x%x)(%x%x)(%x%x)$")
        if not r then
            return nil
        end
        return Color3.fromRGB(tonumber(r, 16), tonumber(g, 16), tonumber(b, 16))
    end

    function Util.colorEquals(a, b)
        return Util.toHex(a) == Util.toHex(b)
    end

    function Util.formatTime(seconds)
        seconds = math.max(0, math.floor(tonumber(seconds) or 0))
        return string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
    end

    function Util.fullName(instance)
        local ok, name = pcall(function()
            return instance:GetFullName()
        end)
        return ok and name or "(unavailable)"
    end

    function Util.truncate(text, maxLength)
        text = tostring(text or "")
        if #text <= maxLength then
            return text
        end
        return string.sub(text, 1, maxLength - 1) .. "…"
    end

    -- Minimal signal used by VEYL's own modules (not Roblox events).
    function Util.signal()
        local signal = { handlers = {} }
        function signal:Connect(callback)
            local handle = { connected = true }
            signal.handlers[handle] = callback
            function handle:Disconnect()
                handle.connected = false
                signal.handlers[handle] = nil
            end
            return handle
        end
        function signal:Fire(...)
            for handle, callback in pairs(signal.handlers) do
                if handle.connected then
                    local ok, err = pcall(callback, ...)
                    if not ok then
                        Log.add("warn", "Internal handler error: " .. tostring(err))
                    end
                end
            end
        end
        return signal
    end

    ----------------------------------------------------------------------------
    -- Lifecycle: Maid owns connections, instances, threads and overlay objects
    ----------------------------------------------------------------------------

    local Maid = {}
    Maid.__index = Maid

    local function cleanupTask(item)
        local kind = typeof(item)
        if kind == "RBXScriptConnection" then
            item:Disconnect()
        elseif kind == "Instance" then
            item:Destroy()
        elseif kind == "function" then
            item()
        elseif kind == "thread" then
            if coroutine.status(item) ~= "running" then
                task.cancel(item)
            end
        elseif kind == "table" then
            if item.Disconnect then
                item:Disconnect()
            elseif item.Destroy then
                item:Destroy()
            end
        end
    end

    function Maid.new()
        return setmetatable({ tasks = {} }, Maid)
    end

    function Maid:give(item)
        if item ~= nil then
            table.insert(self.tasks, item)
        end
        return item
    end

    function Maid:connect(signal, callback)
        return self:give(signal:Connect(callback))
    end

    function Maid:delay(seconds, callback)
        return self:give(task.delay(seconds, function()
            if Session.alive then
                callback()
            end
        end))
    end

    function Maid:clean()
        local tasks = self.tasks
        self.tasks = {}
        for index = #tasks, 1, -1 do
            local ok, err = pcall(cleanupTask, tasks[index])
            if not ok then
                warn("[VEYL] Cleanup error: " .. tostring(err))
            end
        end
    end

    function Maid:Destroy()
        self:clean()
    end

    -- Root owns everything that lives for the whole session.
    local Root = Maid.new()

    ----------------------------------------------------------------------------
    -- Logging (bounded ring buffer)
    ----------------------------------------------------------------------------

    Log.entries = {}
    Log.version = 0

    local LOG_TAGS = { info = "INFO", ok = " OK ", warn = "WARN", error = "FAIL" }

    function Log.add(level, message)
        message = tostring(message)
        table.insert(Log.entries, 1, { time = os.date("%H:%M:%S"), level = level or "info", text = message })
        while #Log.entries > LIMITS.logs do
            table.remove(Log.entries)
        end
        Log.version += 1
        if level == "error" or level == "warn" then
            warn("[VEYL] " .. message)
        else
            print("[VEYL] " .. message)
        end
    end

    function Log.format(entry)
        return string.format("%s [%s] %s", entry.time, LOG_TAGS[entry.level] or "INFO", entry.text)
    end

    function Log.clear()
        table.clear(Log.entries)
        Log.version += 1
    end

    -- Wrap a per-frame step so a broken loop cannot fail forever.
    function Util.guardStep(name, step, onFatal)
        local failures = 0
        return function(...)
            local ok, err = pcall(step, ...)
            if ok then
                failures = 0
                return
            end
            failures += 1
            if failures == 1 then
                Log.add("warn", name .. " error: " .. tostring(err))
            end
            if failures >= 30 then
                failures = 0
                Notify.push(name .. " stopped after 30 consecutive errors: " .. tostring(err), "error")
                if onFatal then
                    onFatal()
                end
            end
        end
    end

    V.Players = Players
    V.RunService = RunService
    V.UserInputService = UserInputService
    V.Lighting = Lighting
    V.SoundService = SoundService
    V.TeleportService = TeleportService
    V.CollectionService = CollectionService
    V.HttpService = HttpService
    V.MarketplaceService = MarketplaceService
    V.ContentProvider = ContentProvider
    V.ReplicatedStorage = ReplicatedStorage
    V.StarterPack = StarterPack
    V.Stats = Stats
    V.Workspace = Workspace
    V.LocalPlayer = LocalPlayer
    V.PlayerGui = PlayerGui
    V.VERSION = VERSION
    V.NAMES = NAMES
    V.LEGACY_INSTANCES = LEGACY_INSTANCES
    V.LIMITS = LIMITS
    V.Util = Util
    V.Log = Log
    V.Notify = Notify
    V.Cap = Cap
    V.Settings = Settings
    V.Binds = Binds
    V.Persist = Persist
    V.UI = UI
    V.Popup = Popup
    V.Overlay = Overlay
    V.Entities = Entities
    V.ESP = ESP
    V.Aim = Aim
    V.World = World
    V.Weapons = Weapons
    V.Diag = Diag
    V.Music = Music
    V.Rejoin = Rejoin
    V.Features = Features
    V.App = App
    V.Session = Session
    V.Maid = Maid
    V.cleanupTask = cleanupTask
    V.Root = Root
    V.LOG_TAGS = LOG_TAGS
end
end)() }
MODULES[#MODULES + 1] = { path = "src/runtime.lua", factory = (function()
-- VEYL module: runtime
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local RunService = V.RunService
    local Lighting = V.Lighting
    local SoundService = V.SoundService
    local Workspace = V.Workspace
    local PlayerGui = V.PlayerGui
    local LEGACY_INSTANCES = V.LEGACY_INSTANCES
    local Util = V.Util
    local Cap = V.Cap
    local Session = V.Session

    ----------------------------------------------------------------------------
    -- 3. Runtime capability detection (optional executor APIs, never assumed)
    ----------------------------------------------------------------------------

    local function isCallable(value)
        return type(value) == "function"
    end

    -- Reading an undefined global returns nil; pcall guards environments that throw.
    local function readGlobal(reader)
        local ok, value = pcall(reader)
        if ok then
            return value
        end
        return nil
    end

    Cap.report = {}

    -- Shared table used only to hand the shutdown function to the next execution.
    Cap.shared = _G
    do
        local getgenvFn = readGlobal(function()
            return getgenv
        end)
        if isCallable(getgenvFn) then
            local ok, env = pcall(getgenvFn)
            if ok and type(env) == "table" then
                Cap.shared = env
            end
        end
    end

    -- Drawing: confirmed by creating and removing one Line object.
    do
        local constructor = readGlobal(function()
            return Drawing.new
        end)
        if isCallable(constructor) then
            local ok, probe = pcall(constructor, "Line")
            if ok and probe ~= nil then
                pcall(function()
                    probe:Remove()
                end)
                Cap.drawingNew = constructor
                Cap.drawingFont = readGlobal(function()
                    return Drawing.Fonts.Plex
                end)
            end
        end
    end

    -- gethui: documented hidden GUI container on runtimes that provide it.
    do
        local gethuiFn = readGlobal(function()
            return gethui
        end)
        if isCallable(gethuiFn) then
            local ok, container = pcall(gethuiFn)
            if ok and typeof(container) == "Instance" then
                Cap.hui = container
            end
        end
    end

    -- Local file API, used only for VEYL's own non-sensitive config.
    do
        local readfileFn = readGlobal(function()
            return readfile
        end)
        local writefileFn = readGlobal(function()
            return writefile
        end)
        local isfileFn = readGlobal(function()
            return isfile
        end)
        if isCallable(readfileFn) and isCallable(writefileFn) and isCallable(isfileFn) then
            local makefolderFn = readGlobal(function()
                return makefolder
            end)
            local isfolderFn = readGlobal(function()
                return isfolder
            end)
            Cap.file = {
                read = readfileFn,
                write = writefileFn,
                isFile = isfileFn,
                makeFolder = isCallable(makefolderFn) and makefolderFn or nil,
                isFolder = isCallable(isfolderFn) and isfolderFn or nil,
            }
            Cap.configFolder = Cap.file.makeFolder and "VEYL" or nil
            Cap.configPath = Cap.file.makeFolder and "VEYL/config.json" or "VEYL_config.json"
        end
    end

    -- Clipboard.
    do
        local clip = readGlobal(function()
            return setclipboard
        end) or readGlobal(function()
            return toclipboard
        end)
        if isCallable(clip) then
            Cap.clipboard = clip
        end
    end

    -- Runtime identity, only through the identification function the runtime exposes.
    do
        local identify = readGlobal(function()
            return identifyexecutor
        end) or readGlobal(function()
            return getexecutorname
        end)
        if isCallable(identify) then
            local ok, name, version = pcall(identify)
            if ok and type(name) == "string" then
                Cap.identity = Util.truncate(name .. (type(version) == "string" and (" " .. version) or ""), 48)
            end
        end
    end

    Cap.script = readGlobal(function()
        return typeof(script) == "Instance" and script or nil
    end)
    Cap.executorAware = (Cap.drawingNew or Cap.hui or Cap.file or Cap.clipboard or Cap.identity) ~= nil
    Cap.studio = RunService:IsStudio()

    function Cap.copy(text)
        if not Cap.clipboard then
            return false
        end
        local ok = pcall(Cap.clipboard, tostring(text))
        return ok
    end

    function Cap.modeText()
        if Cap.identity then
            return Cap.identity
        end
        return Cap.executorAware and "Executor APIs detected" or "Standard client (no executor APIs)"
    end

    function Cap.buildReport(guiParentKind)
        local rows = {}
        local function add(name, status, detail)
            table.insert(rows, { name = name, status = status, detail = detail })
        end
        add("Runtime", "Info", Cap.modeText())
        add("Drawing API", Cap.drawingNew and "Available" or "Fallback", Cap.drawingNew and "Overlay uses Drawing objects" or "Overlay uses ScreenGui frames")
        add("GUI container", guiParentKind == "gethui" and "Available" or "Fallback", guiParentKind == "gethui" and "Parented under gethui()" or "Parented under PlayerGui")
        add("Config files", Cap.file and "Available" or "Unavailable", Cap.file and Cap.configPath or "Settings stay in session memory")
        add("Clipboard", Cap.clipboard and "Available" or "Fallback", Cap.clipboard and "setclipboard" or "Copy from a text box with Ctrl+C")
        add("External URL opening", "Unavailable", "No documented API is used; bookmarks are copy-only")
        add("Highlight", "Available", "Standard Roblox instance")
        add("Teleport (rejoin)", Cap.studio and "Unavailable" or "Available", Cap.studio and "Studio does not support teleports" or "TeleportService")
        add("Script instance", Cap.script and "Available" or "Info", Cap.script and "Destroying cleanup bound" or "Cleanup via session handoff")
        Cap.report = rows
        return rows
    end

    ----------------------------------------------------------------------------
    -- Re-execution safety: stop the previous session, then remove known leftovers
    ----------------------------------------------------------------------------

    do
        local previous = Cap.shared.__VEYL_SESSION
        if type(previous) == "table" and isCallable(previous.shutdown) then
            local ok, err = pcall(previous.shutdown, "re-execution")
            if not ok then
                warn("[VEYL] Previous session shutdown failed: " .. tostring(err))
            end
        end
        Cap.shared.__VEYL_SESSION = nil

        local containers = {
            gui = { PlayerGui, Cap.hui },
            workspace = { Workspace },
            lighting = { Lighting },
            sound = { SoundService },
        }
        local removed = 0
        for _, spec in ipairs(LEGACY_INSTANCES) do
            for _, container in ipairs(containers[spec.where]) do
                if typeof(container) == "Instance" then
                    for _, child in ipairs(container:GetChildren()) do
                        if child.Name == spec.name and child.ClassName == spec.class then
                            local ok = pcall(function()
                                child:Destroy()
                            end)
                            if ok then
                                removed += 1
                            end
                        end
                    end
                end
            end
        end
        Session.legacyRemoved = removed
    end

    V.isCallable = isCallable
    V.readGlobal = readGlobal
end
end)() }
MODULES[#MODULES + 1] = { path = "src/settings.lua", factory = (function()
-- VEYL module: settings
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Lighting = V.Lighting
    local Util = V.Util
    local Log = V.Log
    local Settings = V.Settings

    ----------------------------------------------------------------------------
    -- 4. Settings registry (validated defaults, change listeners, reset)
    ----------------------------------------------------------------------------

    Settings.schema = {}
    Settings.order = {}
    Settings.values = {}
    Settings.listeners = {}
    Settings.changed = Util.signal()

    local function define(key, spec)
        spec.key = key
        if spec.type == "color" then
            spec.default = Util.fromHex(spec.default) or spec.default
        end
        Settings.schema[key] = spec
        table.insert(Settings.order, key)
        Settings.values[key] = spec.default
    end

    local function valuesEqual(a, b)
        if typeof(a) == "Color3" and typeof(b) == "Color3" then
            return Util.colorEquals(a, b)
        end
        return a == b
    end

    function Settings.validate(key, value)
        local spec = Settings.schema[key]
        if not spec then
            return false, nil, "Unknown setting"
        end
        if spec.type == "boolean" then
            if type(value) ~= "boolean" then
                return false, nil, "Expected on/off"
            end
            return true, value
        elseif spec.type == "number" then
            local number = tonumber(value)
            if not number or number ~= number or number == math.huge or number == -math.huge then
                return false, nil, "Enter a number"
            end
            number = math.clamp(number, spec.min, spec.max)
            if spec.step then
                number = spec.min + math.floor((number - spec.min) / spec.step + 0.5) * spec.step
            end
            return true, math.clamp(Util.round(number, 4), spec.min, spec.max)
        elseif spec.type == "enum" then
            if table.find(spec.options, value) then
                return true, value
            end
            return false, nil, "Unsupported option"
        elseif spec.type == "color" then
            if typeof(value) == "Color3" then
                return true, value
            end
            local color = Util.fromHex(value)
            if color then
                return true, color
            end
            return false, nil, "Use #RRGGBB"
        end
        return false, nil, "Unsupported setting type"
    end

    function Settings.get(key)
        return Settings.values[key]
    end

    function Settings.set(key, value)
        local ok, normalized, err = Settings.validate(key, value)
        if not ok then
            return false, nil, err
        end
        if valuesEqual(Settings.values[key], normalized) then
            return true, normalized
        end
        Settings.values[key] = normalized
        local list = Settings.listeners[key]
        if list then
            for handle, callback in pairs(list) do
                if handle.connected then
                    local okCall, callErr = pcall(callback, normalized)
                    if not okCall then
                        Log.add("warn", "Setting listener for " .. key .. " failed: " .. tostring(callErr))
                    end
                end
            end
        end
        Settings.changed:Fire(key, normalized)
        return true, normalized
    end

    function Settings.on(key, callback)
        local list = Settings.listeners[key]
        if not list then
            list = {}
            Settings.listeners[key] = list
        end
        local handle = { connected = true }
        function handle:Disconnect()
            handle.connected = false
            list[handle] = nil
        end
        list[handle] = callback
        return handle
    end

    function Settings.default(key)
        local spec = Settings.schema[key]
        return spec and spec.default
    end

    function Settings.reset(key)
        local spec = Settings.schema[key]
        if spec then
            Settings.set(key, spec.default)
        end
    end

    function Settings.resetPrefix(prefix)
        for _, key in ipairs(Settings.order) do
            if prefix == nil or string.sub(key, 1, #prefix) == prefix then
                Settings.reset(key)
            end
        end
    end

    function Settings.serialize()
        local out = {}
        for _, key in ipairs(Settings.order) do
            local spec = Settings.schema[key]
            if not spec.session then
                local value = Settings.values[key]
                out[key] = typeof(value) == "Color3" and Util.toHex(value) or value
            end
        end
        return out
    end

    function Settings.loadTable(data)
        local applied, rejected = 0, 0
        if type(data) ~= "table" then
            return applied, rejected
        end
        for key, value in pairs(data) do
            local spec = type(key) == "string" and Settings.schema[key]
            if spec and not spec.session then
                local ok = Settings.set(key, value)
                if ok then
                    applied += 1
                else
                    rejected += 1
                end
            else
                rejected += 1
            end
        end
        return applied, rejected
    end

    -- Snapshot of the game's lighting at startup, used as World defaults.
    local LightingStart = {
        Brightness = Lighting.Brightness,
        ExposureCompensation = Lighting.ExposureCompensation,
        ClockTime = Lighting.ClockTime,
        GlobalShadows = Lighting.GlobalShadows,
        Ambient = Lighting.Ambient,
    }

    -- Interface
    define("ui.translucent", { type = "boolean", default = true })
    define("ui.blur", { type = "boolean", default = false })
    define("ui.scale", { type = "number", min = 80, max = 130, step = 5, default = 100 })
    define("ui.toasts", { type = "boolean", default = true })
    define("ui.autosave", { type = "boolean", default = true })

    -- ESP / Visuals
    define("esp.enabled", { type = "boolean", default = false, session = true })
    define("esp.renderer", { type = "enum", options = { "Auto", "Drawing", "GUI" }, default = "Auto" })
    define("esp.maxDistance", { type = "number", min = 50, max = 3000, step = 10, default = 1000 })
    define("esp.boxes", { type = "boolean", default = true })
    define("esp.names", { type = "boolean", default = true })
    define("esp.distance", { type = "boolean", default = true })
    define("esp.health", { type = "boolean", default = true })
    define("esp.tracers", { type = "boolean", default = false })
    define("esp.offscreen", { type = "boolean", default = true })
    define("esp.highlight", { type = "boolean", default = false })
    define("esp.visibility", { type = "boolean", default = true })
    define("esp.visColors", { type = "boolean", default = false })
    define("esp.typeColors", { type = "boolean", default = false })
    define("esp.showTargets", { type = "boolean", default = true })
    define("esp.showNpcs", { type = "boolean", default = true })
    define("esp.showPlayers", { type = "boolean", default = true })
    define("esp.tracerOrigin", { type = "enum", options = { "Bottom", "Center", "Mouse" }, default = "Bottom" })
