MODULES[#MODULES + 1] = { path = "src/binds.lua", factory = (function()
-- VEYL module: binds
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local UserInputService = V.UserInputService
    local Util = V.Util
    local Notify = V.Notify
    local Binds = V.Binds
    local Persist = V.Persist
    local UI = V.UI

    ----------------------------------------------------------------------------
    -- 8. Keybind manager (the single input router lives in app.lua)
    ----------------------------------------------------------------------------

    Binds.actions = {
        { id = "toggleUI", label = "Toggle console", default = "KeyCode.RightShift" },
        { id = "toggleAim", label = "Toggle Aim Lab", default = "KeyCode.Z" },
        { id = "aimHold", label = "Aim Lab hold key", default = "UserInputType.MouseButton2", hold = true },
        { id = "toggleESP", label = "Toggle ESP", default = "KeyCode.X" },
        { id = "cycleTarget", label = "Cycle test target", default = "KeyCode.C" },
        { id = "clearTarget", label = "Clear selected target", default = "KeyCode.V" },
        { id = "emergencyStop", label = "Emergency stop", default = "KeyCode.End", protected = true },
    }
    Binds.byId = {}
    Binds.map = {}
    Binds.lookup = {}
    Binds.enums = {}
    Binds.changed = Util.signal()
    Binds.capturing = nil

    local BIND_MOUSE = { MouseButton2 = "Mouse 2", MouseButton3 = "Mouse 3" }
    local BIND_RESERVED = { Escape = true, Backspace = true, Unknown = true }

    for _, action in ipairs(Binds.actions) do
        Binds.byId[action.id] = action
        Binds.map[action.id] = action.default
    end

    function Binds.parse(text)
        if text == "None" then
            return "None"
        end
        if type(text) ~= "string" then
            return nil
        end
        local enumName, item = string.match(text, "^(%a+)%.(%w+)$")
        if enumName == "KeyCode" and not BIND_RESERVED[item] then
            local ok, keyCode = pcall(function()
                return Enum.KeyCode[item]
            end)
            if ok and keyCode then
                return text
            end
        elseif enumName == "UserInputType" and BIND_MOUSE[item] then
            return text
        end
        return nil
    end

    function Binds.fromInput(input)
        if input.UserInputType == Enum.UserInputType.Keyboard then
            local name = input.KeyCode.Name
            if BIND_RESERVED[name] then
                return nil
            end
            return "KeyCode." .. name
        end
        if BIND_MOUSE[input.UserInputType.Name] then
            return "UserInputType." .. input.UserInputType.Name
        end
        return nil
    end

    function Binds.display(text)
        if not text or text == "None" then
            return "Unbound"
        end
        local enumName, item = string.match(text, "^(%a+)%.(%w+)$")
        if enumName == "UserInputType" then
            return BIND_MOUSE[item] or item
        end
        return item or text
    end

    function Binds.rebuild()
        table.clear(Binds.lookup)
        for id, text in pairs(Binds.map) do
            if text ~= "None" and not Binds.byId[id].hold then
                Binds.lookup[text] = id
            end
            if text ~= "None" and not Binds.enums[text] then
                local enumName, item = string.match(text, "^(%a+)%.(%w+)$")
                local ok, value = pcall(function()
                    if enumName == "KeyCode" then
                        return Enum.KeyCode[item]
                    end
                    return Enum.UserInputType[item]
                end)
                if ok and value then
                    Binds.enums[text] = { kind = enumName, value = value }
                end
            end
        end
    end

    function Binds.ownerOf(text, exceptId)
        for id, bound in pairs(Binds.map) do
            if bound == text and id ~= exceptId then
                return id
            end
        end
        return nil
    end

    function Binds.set(id, text)
        if not Binds.byId[id] or not Binds.parse(text) then
            return false
        end
        Binds.map[id] = text
        Binds.rebuild()
        Binds.changed:Fire(id)
        Persist.schedule()
        return true
    end

    function Binds.reset(id)
        local action = Binds.byId[id]
        if not action then
            return
        end
        local owner = Binds.ownerOf(action.default, id)
        if owner then
            Binds.map[owner] = "None"
            Binds.changed:Fire(owner)
        end
        Binds.set(id, action.default)
    end

    function Binds.resetAll()
        for _, action in ipairs(Binds.actions) do
            Binds.map[action.id] = action.default
        end
        Binds.rebuild()
        for _, action in ipairs(Binds.actions) do
            Binds.changed:Fire(action.id)
        end
        Persist.schedule()
    end

    function Binds.match(input)
        local text = Binds.fromInput(input)
        return text and Binds.lookup[text] or nil
    end

    function Binds.isHeld(id)
        local text = Binds.map[id]
        if not text or text == "None" or UserInputService:GetFocusedTextBox() then
            return false
        end
        local entry = Binds.enums[text]
        if not entry then
            return false
        end
        if entry.kind == "KeyCode" then
            return UserInputService:IsKeyDown(entry.value)
        end
        return UserInputService:IsMouseButtonPressed(entry.value)
    end

    function Binds.loadTable(data)
        if type(data) ~= "table" then
            return
        end
        local used = {}
        for _, action in ipairs(Binds.actions) do
            local text = Binds.parse(data[action.id])
            if text and (text == "None" or not used[text]) and not (action.protected and text == "None") then
                Binds.map[action.id] = text
            end
            if Binds.map[action.id] ~= "None" then
                if used[Binds.map[action.id]] then
                    -- A collision in a hand-edited file falls back to that action's default.
                    Binds.map[action.id] = action.default
                end
                used[Binds.map[action.id]] = true
            end
        end
        Binds.rebuild()
    end

    function Binds.beginCapture(id)
        if Binds.capturing then
            Binds.cancelCapture()
        end
        Binds.capturing = { id = id }
        Binds.changed:Fire(id)
    end

    function Binds.cancelCapture()
        local capture = Binds.capturing
        Binds.capturing = nil
        if capture then
            Binds.changed:Fire(capture.id)
        end
    end

    function Binds.handleCapture(input)
        local capture = Binds.capturing
        local inputType = input.UserInputType
        if inputType == Enum.UserInputType.MouseMovement or inputType == Enum.UserInputType.MouseButton1
            or inputType == Enum.UserInputType.MouseWheel or inputType == Enum.UserInputType.Focus then
            return
        end
        local id = capture.id
        local action = Binds.byId[id]
        if inputType == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Escape then
            Binds.cancelCapture()
            Notify.push("Rebind cancelled.", "info")
            return
        end
        if inputType == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Backspace then
            Binds.capturing = nil
            if action.protected then
                Binds.changed:Fire(id)
                Notify.push(action.label .. " cannot be unbound. Rebind it to another key instead.", "warn")
                return
            end
            Binds.set(id, "None")
            Notify.push(action.label .. " is now unbound.", "info")
            return
        end
        local text = Binds.fromInput(input)
        if not text then
            Notify.push("That input cannot be bound. Use a keyboard key, Mouse 2 or Mouse 3.", "warn")
            return
        end
        Binds.capturing = nil
        if text == Binds.map[id] then
            Binds.changed:Fire(id)
            return
        end
        local owner = Binds.ownerOf(text, id)
        if owner and Binds.byId[owner].protected then
            Binds.changed:Fire(id)
            Notify.push(Binds.display(text) .. " is the emergency stop key. Rebind emergency stop first.", "warn")
            return
        end
        local function apply()
            if owner then
                Binds.map[owner] = "None"
                Binds.changed:Fire(owner)
            end
            Binds.set(id, text)
            Notify.push(action.label .. " → " .. Binds.display(text), "ok")
        end
        if owner or action.protected then
            local lines = {}
            if action.protected then
                table.insert(lines, "Rebind the emergency stop to " .. Binds.display(text) .. "?")
            end
            if owner then
                table.insert(lines, Binds.display(text) .. " is bound to " .. Binds.byId[owner].label .. ". Reassigning leaves that action unbound.")
            end
            Binds.changed:Fire(id)
            UI.confirm("Confirm keybind", table.concat(lines, "\n"), "Reassign", apply)
        else
            apply()
        end
    end

    Binds.rebuild()

    V.BIND_MOUSE = BIND_MOUSE
    V.BIND_RESERVED = BIND_RESERVED
end
end)() }
MODULES[#MODULES + 1] = { path = "src/persist.lua", factory = (function()
-- VEYL module: persist
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local HttpService = V.HttpService
    local LIMITS = V.LIMITS
    local Log = V.Log
    local Notify = V.Notify
    local Cap = V.Cap
    local Settings = V.Settings
    local Binds = V.Binds
    local Persist = V.Persist
    local Music = V.Music
    local Session = V.Session

    ----------------------------------------------------------------------------
    -- 18. Settings persistence (only when the runtime exposes a file API)
    ----------------------------------------------------------------------------

    Persist.available = Cap.file ~= nil
    Persist.status = Persist.available and "Not saved yet" or "Session only (no file API)"
    Persist.token = 0
    Persist.loading = false

    function Persist.encode()
        return HttpService:JSONEncode({
            app = "VEYL Control",
            version = 1,
            settings = Settings.serialize(),
            binds = table.clone(Binds.map),
            music = Music.serialize(),
        })
    end

    function Persist.save(manual)
        if not Persist.available then
            if manual then
                Notify.push("This runtime has no file API. Settings stay in session memory.", "warn")
            end
            return false
        end
        local ok, err = pcall(function()
            local file = Cap.file
            if Cap.configFolder then
                local exists = false
                if file.isFolder then
                    local okFolder, result = pcall(file.isFolder, Cap.configFolder)
                    exists = okFolder and result == true
                end
                if not exists then
                    pcall(file.makeFolder, Cap.configFolder)
                end
            end
            file.write(Cap.configPath, Persist.encode())
        end)
        if ok then
            Persist.dirty = false
            Persist.status = "Saved " .. os.date("%H:%M:%S") .. " · " .. Cap.configPath
            if manual then
                Notify.push("Configuration saved to " .. Cap.configPath .. ".", "ok")
            end
        else
            Persist.status = "Save failed"
            Log.add("error", "Config save failed: " .. tostring(err))
            if manual then
                Notify.push("Config save failed: " .. tostring(err), "error")
            end
        end
        return ok
    end

    function Persist.schedule()
        if not Persist.available or Persist.loading or not Session.alive or not Settings.get("ui.autosave") then
            return
        end
        Persist.token += 1
        Persist.dirty = true
        local token = Persist.token
        task.delay(1.5, function()
            if Session.alive and token == Persist.token then
                Persist.save(false)
            end
        end)
    end

    function Persist.load(manual)
        if not Persist.available then
            if manual then
                Notify.push("This runtime has no file API to load from.", "warn")
            end
            return false
        end
        local okExists, exists = pcall(Cap.file.isFile, Cap.configPath)
        if not okExists or not exists then
            Persist.status = "No saved config yet"
            if manual then
                Notify.push("No saved configuration was found.", "warn")
            end
            return false
        end
        local okRead, content = pcall(Cap.file.read, Cap.configPath)
        if not okRead or type(content) ~= "string" then
            Persist.status = "Read failed"
            Log.add("error", "Config read failed: " .. tostring(content))
            return false
        end
        if #content > LIMITS.configBytes then
            Persist.status = "Rejected (file too large)"
            Log.add("warn", "Config ignored: file exceeds " .. LIMITS.configBytes .. " bytes.")
            return false
        end
        local okDecode, data = pcall(function()
            return HttpService:JSONDecode(content)
        end)
        if not okDecode or type(data) ~= "table" or data.app ~= "VEYL Control" then
            Persist.status = "Rejected (malformed file)"
            Log.add("warn", "Config ignored: the file is not a valid VEYL configuration.")
            if manual then
                Notify.push("The saved configuration is malformed and was ignored.", "error")
            end
            return false
        end
        Persist.loading = true
        local applied, rejected = Settings.loadTable(data.settings)
        Binds.loadTable(data.binds)
        for _, action in ipairs(Binds.actions) do
            Binds.changed:Fire(action.id)
        end
        Music.loadTable(data.music)
        Persist.loading = false
        Persist.status = string.format("Loaded %d values%s · %s", applied, rejected > 0 and (" (" .. rejected .. " rejected)") or "", Cap.configPath)
        Log.add("info", "Configuration loaded: " .. applied .. " values applied, " .. rejected .. " rejected.")
        if manual then
            Notify.push("Configuration reloaded.", "ok")
        end
        return true
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/ui/window.lua", factory = (function()
-- VEYL module: ui/window
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Lighting = V.Lighting
    local Workspace = V.Workspace
    local PlayerGui = V.PlayerGui
    local VERSION = V.VERSION
    local NAMES = V.NAMES
    local Util = V.Util
    local Log = V.Log
    local Notify = V.Notify
    local Cap = V.Cap
    local Settings = V.Settings
    local Binds = V.Binds
    local UI = V.UI
    local Popup = V.Popup
    local Music = V.Music
    local Session = V.Session
    local Root = V.Root

    ----------------------------------------------------------------------------
    -- 6. UI component builders
    ----------------------------------------------------------------------------

    local T = {
        bg = Color3.fromRGB(12, 15, 21),
        title = Color3.fromRGB(16, 20, 28),
        panel = Color3.fromRGB(18, 22, 31),
        raised = Color3.fromRGB(26, 31, 42),
        field = Color3.fromRGB(10, 13, 19),
        hover = Color3.fromRGB(34, 41, 56),
        line = Color3.fromRGB(44, 52, 68),
        lineSoft = Color3.fromRGB(31, 37, 50),
        text = Color3.fromRGB(226, 232, 242),
        muted = Color3.fromRGB(140, 151, 171),
        dim = Color3.fromRGB(96, 106, 124),
        accent = Color3.fromRGB(64, 156, 255),
        accentHover = Color3.fromRGB(92, 172, 255),
        cyan = Color3.fromRGB(56, 214, 230),
        ok = Color3.fromRGB(88, 214, 141),
        warn = Color3.fromRGB(255, 190, 92),
        bad = Color3.fromRGB(255, 99, 110),
        badDim = Color3.fromRGB(110, 38, 50),
        badHover = Color3.fromRGB(140, 48, 62),
        font = Enum.Font.Gotham,
        fontMedium = Enum.Font.GothamMedium,
        fontBold = Enum.Font.GothamBold,
        mono = Enum.Font.Code,
    }

    local STATUS_COLORS = { Available = T.ok, Fallback = T.warn, Unavailable = T.bad, Info = T.muted }

    local function make(className, properties, parent)
        local instance = Instance.new(className)
        if properties then
            for property, value in pairs(properties) do
                instance[property] = value
            end
        end
        if parent then
            instance.Parent = parent
        end
        return instance
    end

    local function corner(parent, radius)
        return make("UICorner", { CornerRadius = UDim.new(0, radius or 6) }, parent)
    end

    local function stroke(parent, color, transparency, thickness)
        return make("UIStroke", {
            Color = color or T.line,
            Transparency = transparency or 0,
            Thickness = thickness or 1,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        }, parent)
    end

    local function padding(parent, left, right, top, bottom)
        return make("UIPadding", {
            PaddingLeft = UDim.new(0, left or 0),
            PaddingRight = UDim.new(0, right or 0),
            PaddingTop = UDim.new(0, top or 0),
            PaddingBottom = UDim.new(0, bottom or 0),
        }, parent)
    end

    local function vlist(parent, gap)
        return make("UIListLayout", {
            Padding = UDim.new(0, gap or 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
            FillDirection = Enum.FillDirection.Vertical,
        }, parent)
    end

    local function text(parent, properties)
        local label = make("TextLabel", {
            BackgroundTransparency = 1,
            Font = T.font,
            TextColor3 = T.text,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        })
        for property, value in pairs(properties) do
            label[property] = value
        end
        label.Parent = parent
        return label
    end

    local function isPress(input)
        return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
    end

    UI.pages = {}
    UI.pageOrder = {}
    UI.sections = {}
    UI.open = true
    UI.minimized = false
    UI.dragging = nil
    UI.MIN_SIZE = Vector2.new(560, 380)
    UI.DEFAULT_HINT = "Hover a control for details · right-click a setting to reset it"

    function UI.flashError(target)
        if not target then
            return
        end
        local original = T.lineSoft
        target.Color = T.bad
        task.delay(1.2, function()
            if target.Parent then
                target.Color = original
            end
        end)
    end

    function UI.setHint(message)
        if UI.hintLabel then
            UI.hintLabel.Text = message or UI.DEFAULT_HINT
        end
    end

    function UI.flashStatus(message, color, seconds)
        if UI.status then
            UI.status.Text = message
            UI.status.TextColor3 = color or T.muted
            UI.statusUntil = os.clock() + (seconds or 3)
        end
    end

    function UI.refreshStatus()
        if not UI.status or (UI.statusUntil and os.clock() < UI.statusUntil) then
            return
        end
        local parts = {}
        if Settings.get("aim.enabled") then
            table.insert(parts, "AIM")
        end
        if Settings.get("esp.enabled") then
            table.insert(parts, "ESP")
        end
        if Settings.get("world.enabled") then
            table.insert(parts, "WORLD")
        end
        if Music.isPlaying() then
            table.insert(parts, "♪")
        end
        UI.status.Text = #parts > 0 and ("● " .. table.concat(parts, " · ")) or "● Idle"
        UI.status.TextColor3 = #parts > 0 and T.cyan or T.muted
    end

    function UI.updateBlur()
        local wanted = Session.alive and UI.open and Settings.get("ui.blur")
        if wanted then
            if not UI.blur or not UI.blur.Parent then
                UI.blur = make("BlurEffect", { Name = NAMES.blur, Size = 8 })
                UI.blur:SetAttribute(NAMES.owned, true)
                UI.blur.Parent = Lighting
            end
        elseif UI.blur then
            UI.blur:Destroy()
            UI.blur = nil
        end
    end

    function UI.setOpen(open)
        UI.open = open
        if UI.window then
            UI.window.Visible = open
            UI.reopen.Visible = not open
        end
        if not open then
            Popup.close()
            Binds.cancelCapture()
            UI.dragging = nil
        end
        UI.updateBlur()
    end

    function UI.setMinimized(minimized)
        UI.minimized = minimized
        UI.tabBar.Visible = not minimized
        UI.body.Visible = not minimized
        UI.hintBar.Visible = not minimized
        UI.grip.Visible = not minimized
        UI.minimizeButton.Text = minimized and "▢" or "–"
        UI.window.Size = UDim2.fromOffset(UI.size.X, minimized and 32 or UI.size.Y)
        if minimized then
            Popup.close()
        end
        UI.clampWindow()
    end

    function UI.clampWindow()
        local window, gui = UI.window, UI.gui
        if not window or not gui then
            return
        end
        local screen = gui.AbsoluteSize
        local size = window.AbsoluteSize
        local position = window.Position
        window.Position = UDim2.fromOffset(
            math.clamp(position.X.Offset, 0, math.max(0, screen.X - size.X)),
            math.clamp(position.Y.Offset, 0, math.max(0, screen.Y - size.Y))
        )
    end

    function UI.setSize(width, height)
        local screen = UI.gui.AbsoluteSize
        local scale = UI.scale and UI.scale.Scale or 1
        local maxWidth = math.max(240, (screen.X - 8) / scale)
        local maxHeight = math.max(200, (screen.Y - 8) / scale)
        width = math.clamp(width, math.min(UI.MIN_SIZE.X, maxWidth), maxWidth)
        height = math.clamp(height, math.min(UI.MIN_SIZE.Y, maxHeight), maxHeight)
        UI.size = Vector2.new(math.floor(width), math.floor(height))
        UI.window.Size = UDim2.fromOffset(UI.size.X, UI.minimized and 32 or UI.size.Y)
        UI.clampWindow()
    end

    local function applyTranslucency()
        local on = Settings.get("ui.translucent")
        if UI.window then
            UI.window.BackgroundTransparency = on and 0.06 or 0
        end
        for _, section in ipairs(UI.sections) do
            if section.frame.Parent then
                section.frame.BackgroundTransparency = on and 0.15 or 0
            end
        end
    end

    function UI.build()
        local gui = make("ScreenGui", {
