        }, row)
        corner(track, 3)
        local fill = make("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = T.accent, BorderSizePixel = 0 }, track)
        corner(fill, 3)
        local knob = make("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0, 0.5),
            Size = UDim2.fromOffset(10, 10),
            BackgroundColor3 = T.text,
            BorderSizePixel = 0,
        }, track)
        corner(knob, 5)
        local function render(value)
            local fraction = math.clamp((value - spec.min) / math.max(spec.max - spec.min, 1e-6), 0, 1)
            fill.Size = UDim2.fromScale(fraction, 1)
            knob.Position = UDim2.fromScale(fraction, 0.5)
            if not box:IsFocused() then
                box.Text = Util.formatNumber(value, decimals) .. suffix
            end
        end
        render(Settings.get(options.key))
        maid:give(Settings.on(options.key, render))
        local function setFromX(x)
            local fraction = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
            Settings.set(options.key, spec.min + fraction * (spec.max - spec.min))
        end
        maid:connect(track.InputBegan, function(input)
            if record.enabled == false or not isPress(input) then
                return
            end
            UI.dragging = {
                update = function(position)
                    if track.Parent then
                        setFromX(position.X)
                    end
                end,
            }
            setFromX(input.Position.X)
        end)
        maid:connect(track.MouseButton2Click, function()
            resetFromRow(record, options)
        end)
        maid:connect(box.FocusLost, function()
            if record.enabled == false then
                render(Settings.get(options.key))
                return
            end
            local raw = string.gsub(box.Text, "[^%d%.%-]", "")
            local entered = tonumber(raw)
            if not entered then
                UI.flashError(boxStroke)
                Notify.push(string.format("%s: enter a number from %s to %s.", options.label, Util.formatNumber(spec.min, decimals), Util.formatNumber(spec.max, decimals)), "warn")
            else
                local ok, normalized = Settings.set(options.key, entered)
                if ok and math.abs(normalized - entered) > 1e-6 then
                    Notify.push(string.format("%s set to %s%s (allowed %s–%s, step %s).", options.label, Util.formatNumber(normalized, decimals), suffix, Util.formatNumber(spec.min, decimals), Util.formatNumber(spec.max, decimals), tostring(spec.step)), "info")
                end
            end
            render(Settings.get(options.key))
        end)
        return makeControl(row, record)
    end

    local function fieldButton(parent, width, maid)
        local button = make("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -2, 0.5, 0),
            Size = UDim2.fromOffset(width, 20),
            BackgroundColor3 = T.field,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
        }, parent)
        corner(button, 4)
        local buttonStroke = stroke(button, T.lineSoft)
        maid:connect(button.MouseEnter, function()
            buttonStroke.Color = T.line
        end)
        maid:connect(button.MouseLeave, function()
            buttonStroke.Color = T.lineSoft
        end)
        return button
    end

    function UI.dropdown(section, options, maid)
        maid = maid or Root
        local spec = options.key and Settings.schema[options.key]
        local getOptions = options.options or function()
            return spec.options
        end
        local getValue = options.get or function()
            return Settings.get(options.key)
        end
        local setValue = options.set or function(value)
            Settings.set(options.key, value)
        end
        local row, record = UI.row(section, 22, options, maid)
        local width = options.width or 136
        rowLabel(row, options.label, width + 6)
        local button = fieldButton(row, width, maid)
        local valueLabel = text(button, { Position = UDim2.fromOffset(7, 0), Size = UDim2.new(1, -24, 1, 0), TextSize = 11, Text = "" })
        text(button, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, 0), Size = UDim2.fromOffset(10, 20), Text = "▾", TextColor3 = T.muted, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right })
        local function render()
            local value = getValue()
            local valid = table.find(getOptions(), value) ~= nil
            valueLabel.Text = tostring(value) .. (valid and "" or " (unavailable)")
            valueLabel.TextColor3 = valid and T.text or T.warn
        end
        render()
        if options.key then
            maid:give(Settings.on(options.key, render))
        end
        maid:connect(button.Activated, function()
            if record.enabled ~= false then
                Popup.select(button, getOptions(), getValue(), function(value)
                    setValue(value)
                    render()
                end)
            end
        end)
        maid:connect(button.MouseButton2Click, function()
            resetFromRow(record, options)
        end)
        local control = makeControl(row, record)
        control.refresh = render
        return control
    end

    function UI.color(section, options, maid)
        maid = maid or Root
        local row, record = UI.row(section, 22, options, maid)
        rowLabel(row, options.label, 110)
        local hex = text(row, {
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, -40, 0, 0),
            Size = UDim2.fromOffset(64, 22),
            Font = T.mono,
            TextSize = 11,
            TextColor3 = T.muted,
            TextXAlignment = Enum.TextXAlignment.Right,
        })
        local swatch = make("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -4, 0.5, 0),
            Size = UDim2.fromOffset(30, 14),
            BorderSizePixel = 0,
            Text = "",
            AutoButtonColor = false,
        }, row)
        corner(swatch, 3)
        stroke(swatch, T.line)
        local function render(color)
            swatch.BackgroundColor3 = color
            hex.Text = Util.toHex(color)
        end
        render(Settings.get(options.key))
        maid:give(Settings.on(options.key, render))
        local opener = make("TextButton", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0, 110, 1, 0), Text = "", AutoButtonColor = false }, row)
        maid:connect(opener.Activated, function()
            if record.enabled ~= false then
                Popup.colorPicker(swatch, options.key, options.label)
            end
        end)
        maid:connect(opener.MouseButton2Click, function()
            resetFromRow(record, options)
        end)
        return makeControl(row, record)
    end

    function UI.keybind(section, actionId, maid)
        maid = maid or Root
        local action = Binds.byId[actionId]
        local options = {
            label = action.label,
            desc = action.protected and "Click, then press a key. Changing the emergency stop asks for confirmation." or "Click, then press a key or Mouse 2/3. Esc cancels, Backspace unbinds.",
        }
        local row, record = UI.row(section, 22, options, maid)
        rowLabel(row, action.label .. (action.protected and "  ⚑" or ""), 146)
        local button = fieldButton(row, 112, maid)
        button.Position = UDim2.new(1, -28, 0.5, 0)
        local valueLabel = text(button, { Size = UDim2.fromScale(1, 1), TextSize = 11, Font = T.fontMedium, TextXAlignment = Enum.TextXAlignment.Center, Text = "" })
        local reset = make("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -2, 0.5, 0),
            Size = UDim2.fromOffset(22, 20),
            BackgroundColor3 = T.raised,
            BorderSizePixel = 0,
            Text = "↺",
            Font = T.fontBold,
            TextSize = 12,
            TextColor3 = T.muted,
        }, row)
        corner(reset, 4)
        local function render()
            if Binds.capturing and Binds.capturing.id == actionId then
                valueLabel.Text = "Press a key…"
                valueLabel.TextColor3 = T.accent
            else
                local bound = Binds.map[actionId]
                valueLabel.Text = Binds.display(bound)
                valueLabel.TextColor3 = bound == "None" and T.dim or T.text
            end
        end
        render()
        maid:give(Binds.changed:Connect(function(id)
            if id == actionId then
                render()
            end
        end))
        maid:connect(button.Activated, function()
            Binds.beginCapture(actionId)
            UI.setHint("Press a key or Mouse 2/3 · Esc cancels · Backspace unbinds")
        end)
        maid:connect(reset.Activated, function()
            Binds.cancelCapture()
            Binds.reset(actionId)
            Notify.push(action.label .. " reset to " .. Binds.display(action.default) .. ".", "info")
        end)
        return makeControl(row, record)
    end

    local BUTTON_STYLES = {
        default = { T.raised, T.hover, T.text },
        primary = { T.accent, T.accentHover, Color3.new(1, 1, 1) },
        danger = { T.badDim, T.badHover, Color3.fromRGB(255, 220, 225) },
    }

    local function styledButton(parent, label, style, maid)
        local colors = BUTTON_STYLES[style or "default"]
        local button = make("TextButton", {
            BackgroundColor3 = colors[1],
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Font = T.fontMedium,
            Text = label,
            TextColor3 = colors[3],
            TextSize = 11,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, parent)
        corner(button, 4)
        maid:connect(button.MouseEnter, function()
            button.BackgroundColor3 = colors[2]
        end)
        maid:connect(button.MouseLeave, function()
            button.BackgroundColor3 = colors[1]
        end)
        return button
    end
    UI.styledButton = styledButton

    local function safeCallback(callback, label)
        local ok, err = pcall(callback)
        if not ok then
            Notify.push((label or "Action") .. " failed: " .. tostring(err), "error")
        end
    end

    function UI.button(section, options, maid)
        maid = maid or Root
        local row, record = UI.row(section, 24, { label = options.text, desc = options.desc, search = options.search }, maid)
        local button = styledButton(row, options.text, options.style, maid)
        button.Size = UDim2.fromScale(1, 1)
        maid:connect(button.Activated, function()
            if record.enabled ~= false then
                safeCallback(options.callback, options.text)
            end
        end)
        local control = makeControl(row, record)
        control.button = button
        return control
    end

    function UI.buttons(section, list, desc, maid)
        maid = maid or Root
        local labels = {}
        for _, item in ipairs(list) do
            table.insert(labels, item.text)
        end
        local row, record = UI.row(section, 24, { label = table.concat(labels, " "), desc = desc }, maid)
        make("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, row)
        local buttons = {}
        local count = #list
        for index, item in ipairs(list) do
            local button = styledButton(row, item.text, item.style, maid)
            button.LayoutOrder = index
            button.Size = UDim2.new(1 / count, -math.ceil(4 * (count - 1) / count), 1, 0)
            maid:connect(button.Activated, function()
                if record.enabled ~= false then
                    safeCallback(item.callback, item.text)
                end
            end)
            buttons[index] = button
        end
        local control = makeControl(row, record)
        control.buttons = buttons
        return control
    end

    function UI.info(section, options, maid)
        maid = maid or Root
        local row, record = UI.row(section, 20, options, maid)
        text(row, { Position = UDim2.fromOffset(4, 0), Size = UDim2.new(0.42, -4, 1, 0), Text = options.label, TextColor3 = T.muted, TextSize = 11 })
        local value = text(row, {
            Position = UDim2.fromScale(0.42, 0),
            Size = UDim2.new(0.58, -4, 1, 0),
            Text = options.value or "—",
            TextSize = 11,
            Font = T.fontMedium,
            TextXAlignment = Enum.TextXAlignment.Right,
        })
        local control = makeControl(row, record)
        function control.set(message, color)
            value.Text = message
            value.TextColor3 = color or T.text
        end
        return control
    end

    function UI.note(section, message, color, maid)
        maid = maid or Root
        local row, record = UI.row(section, 0, { label = message }, maid)
        row.AutomaticSize = Enum.AutomaticSize.Y
        local label = text(row, {
            Position = UDim2.fromOffset(4, 0),
            Size = UDim2.new(1, -8, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            Text = message,
            TextColor3 = color or T.muted,
            TextSize = 11,
            TextWrapped = true,
            TextTruncate = Enum.TextTruncate.None,
        })
        padding(row, 0, 0, 2, 2)
        local control = makeControl(row, record)
        function control.set(newText, newColor)
            label.Text = newText
            if newColor then
                label.TextColor3 = newColor
            end
        end
        return control
    end

    function UI.input(section, options, maid)
        maid = maid or Root
        local row, record = UI.row(section, 24, options, maid)
        local buttonWidth = options.buttonWidth or 84
        local box = make("TextBox", {
            Size = UDim2.new(1, -(buttonWidth + 4), 1, 0),
            BackgroundColor3 = T.field,
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Font = T.font,
            PlaceholderColor3 = T.dim,
            PlaceholderText = options.placeholder or "",
            Text = "",
            TextColor3 = T.text,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, row)
        corner(box, 4)
        padding(box, 7, 7, 0, 0)
        local boxStroke = stroke(box, T.lineSoft)
        local button = styledButton(row, options.buttonText or "Apply", "primary", maid)
        button.AnchorPoint = Vector2.new(1, 0)
        button.Position = UDim2.fromScale(1, 0)
        button.Size = UDim2.new(0, buttonWidth, 1, 0)
        local function submit()
            if record.enabled == false then
                return
            end
            local ok, result = pcall(options.onSubmit, box.Text)
            if not ok then
                Notify.push("Input failed: " .. tostring(result), "error")
            elseif result then
                box.Text = ""
            else
                UI.flashError(boxStroke)
            end
        end
        maid:connect(button.Activated, submit)
        maid:connect(box.FocusLost, function(enterPressed)
            if enterPressed then
                submit()
            end
        end)
        local control = makeControl(row, record)
        control.box = box
        return control
    end

    -- Search box that is not a settings row (used by list views).
    function UI.filterBox(section, placeholder, onChanged, maid)
        maid = maid or Root
        local row, record = UI.row(section, 22, { label = placeholder }, maid)
        local box = make("TextBox", {
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = T.field,
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Font = T.font,
            PlaceholderColor3 = T.dim,
            PlaceholderText = placeholder,
            Text = "",
            TextColor3 = T.text,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, row)
        corner(box, 4)
        padding(box, 7, 7, 0, 0)
        stroke(box, T.lineSoft)
        maid:connect(box:GetPropertyChangedSignal("Text"), function()
            onChanged(string.lower(Util.trim(box.Text)))
        end)
        record.follow = true
        return box
    end

    -- Keyed list with per-row lifecycles; rows are updated in place, never rebuilt per frame.
    function UI.list(section, emptyText)
        local holder = make("Frame", {
            Name = "List",
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            LayoutOrder = section.nextOrder(),
        }, section.frame)
        vlist(holder, 3)
        local empty = text(holder, {
            Size = UDim2.new(1, 0, 0, 22),
            Text = emptyText or "Nothing here yet.",
            TextColor3 = T.dim,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Center,
            LayoutOrder = -1,
        })
        table.insert(section.rows, { frame = holder, section = section, follow = true, text = "" })
        local list = { holder = holder, rows = {}, count = 0 }
        function list.add(key, height, build)
            local existing = list.rows[key]
            if existing then
                return existing
            end
            local maid = Maid.new()
            local frame = make("Frame", {
                BackgroundColor3 = T.raised,
                BackgroundTransparency = 0.25,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, height),
            })
            corner(frame, 4)
            maid:give(frame)
            local entry = { frame = frame, maid = maid }
            local ok, updater = pcall(build, frame, maid)
            if not ok then
                maid:clean()
                Log.add("warn", "List row failed to build: " .. tostring(updater))
                return nil
            end
            entry.update = updater
            frame.Parent = holder
            list.rows[key] = entry
            list.count += 1
            empty.Visible = false
            return entry
        end
        function list.get(key)
            return list.rows[key]
        end
        function list.remove(key)
            local entry = list.rows[key]
            if entry then
                list.rows[key] = nil
                list.count -= 1
                entry.maid:clean()
            end
            empty.Visible = list.count == 0
        end
        function list.clear()
            for key in pairs(list.rows) do
                list.remove(key)
            end
            empty.Visible = true
        end
        function list.setEmpty(message)
            empty.Text = message
        end
        return list
    end

    V.resetFromRow = resetFromRow
    V.rowLabel = rowLabel
    V.makeControl = makeControl
    V.fieldButton = fieldButton
    V.BUTTON_STYLES = BUTTON_STYLES
    V.styledButton = styledButton
    V.safeCallback = safeCallback
end
end)() }
MODULES[#MODULES + 1] = { path = "src/ui/popups.lua", factory = (function()
-- VEYL module: ui/popups
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Util = V.Util
    local Notify = V.Notify
    local Cap = V.Cap
    local Settings = V.Settings
    local UI = V.UI
    local Popup = V.Popup
    local Maid = V.Maid
    local T = V.T
    local make = V.make
    local corner = V.corner
    local stroke = V.stroke
    local padding = V.padding
    local vlist = V.vlist
    local text = V.text
    local isPress = V.isPress
    local styledButton = V.styledButton
    local safeCallback = V.safeCallback

    ----------------------------------------------------------------------------
    -- 9. Popups: dropdown, confirm, text viewer, color picker
    ----------------------------------------------------------------------------

    function Popup.isOpen()
        return Popup.maid ~= nil
    end

    function Popup.close()
        local maid = Popup.maid
        Popup.maid = nil
        if maid then
            maid:clean()
        end
    end

    function Popup.open(size, anchor, modal)
        Popup.close()
        local layer = UI.popupLayer
        local maid = Maid.new()
        Popup.maid = maid
        local blocker = make("TextButton", {
            BackgroundColor3 = Color3.new(0, 0, 0),
            BackgroundTransparency = modal and 0.55 or 1,
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 1),
            Text = "",
            AutoButtonColor = false,
        }, layer)
        maid:give(blocker)
        maid:connect(blocker.Activated, function()
            Popup.close()
        end)
        local frame = make("Frame", {
            BackgroundColor3 = T.raised,
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(size.X, size.Y),
            Active = true,
        }, layer)
        corner(frame, 6)
        stroke(frame, T.line)
        maid:give(frame)
        local layerPosition, screen = layer.AbsolutePosition, layer.AbsoluteSize
        local x, y
        if anchor then
            local anchorPosition, anchorSize = anchor.AbsolutePosition - layerPosition, anchor.AbsoluteSize
            x = anchorPosition.X + anchorSize.X - size.X
            y = anchorPosition.Y + anchorSize.Y + 4
            if y + size.Y > screen.Y - 4 then
                y = anchorPosition.Y - size.Y - 4
            end
        else
            x = (screen.X - size.X) / 2
            y = (screen.Y - size.Y) / 2
        end
        x = math.clamp(x, 4, math.max(4, screen.X - size.X - 4))
        y = math.clamp(y, 4, math.max(4, screen.Y - size.Y - 4))
        frame.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
        maid:give(function()
            if UI.dragging and UI.dragging.owner == maid then
                UI.dragging = nil
            end
        end)
        return frame, maid
    end

    function Popup.select(anchor, options, current, onPick)
        local itemHeight = 22
        local visible = math.clamp(#options, 1, 8)
        local width = math.max(anchor.AbsoluteSize.X, 150)
        local frame, maid = Popup.open(Vector2.new(width, visible * itemHeight + 8), anchor, false)
        local scroll = make("ScrollingFrame", {
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 1),
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 3,
            ScrollBarImageColor3 = T.line,
        }, frame)
        padding(scroll, 4, 4, 4, 4)
        vlist(scroll, 0)
        if #options == 0 then
            text(scroll, { Size = UDim2.new(1, 0, 0, itemHeight), Text = "No options available", TextColor3 = T.dim, TextSize = 11 })
        end
        for index, option in ipairs(options) do
            local selected = option == current
            local button = make("TextButton", {
                BackgroundColor3 = selected and T.accent or T.hover,
                BackgroundTransparency = selected and 0.2 or 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Size = UDim2.new(1, 0, 0, itemHeight),
                Font = selected and T.fontMedium or T.font,
                Text = "  " .. tostring(option),
                TextColor3 = T.text,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = index,
            }, scroll)
            corner(button, 3)
            maid:connect(button.MouseEnter, function()
                if not selected then
                    button.BackgroundTransparency = 0.3
                end
            end)
            maid:connect(button.MouseLeave, function()
                if not selected then
                    button.BackgroundTransparency = 1
                end
            end)
            maid:connect(button.Activated, function()
                Popup.close()
                onPick(option)
            end)
        end
    end

    function UI.confirm(title, message, confirmText, onConfirm, onCancel)
        local frame, maid = Popup.open(Vector2.new(340, 150), nil, true)
        padding(frame, 12, 12, 10, 10)
        text(frame, { Size = UDim2.new(1, 0, 0, 18), Text = title, Font = T.fontBold, TextSize = 13 })
        text(frame, {
            Position = UDim2.fromOffset(0, 24),
            Size = UDim2.new(1, 0, 1, -56),
            Text = message,
            TextColor3 = T.muted,
            TextWrapped = true,
            TextTruncate = Enum.TextTruncate.None,
            TextYAlignment = Enum.TextYAlignment.Top,
        })
        local decided = false
        local cancel = styledButton(frame, "Cancel", "default", maid)
        cancel.AnchorPoint = Vector2.new(1, 1)
        cancel.Position = UDim2.new(1, -104, 1, 0)
        cancel.Size = UDim2.fromOffset(96, 24)
        local accept = styledButton(frame, confirmText or "Confirm", "primary", maid)
        accept.AnchorPoint = Vector2.new(1, 1)
        accept.Position = UDim2.fromScale(1, 1)
        accept.Size = UDim2.fromOffset(96, 24)
        maid:connect(cancel.Activated, function()
            Popup.close()
        end)
        maid:connect(accept.Activated, function()
            decided = true
            Popup.close()
            safeCallback(onConfirm, title)
        end)
        maid:give(function()
            if not decided and onCancel then
                safeCallback(onCancel, title)
            end
        end)
    end

    function Popup.textViewer(title, body)
        local frame, maid = Popup.open(Vector2.new(440, 280), nil, true)
        padding(frame, 10, 10, 8, 10)
        text(frame, { Size = UDim2.new(1, -30, 0, 18), Text = title, Font = T.fontBold, TextSize = 13 })
        text(frame, { Position = UDim2.fromOffset(0, 18), Size = UDim2.new(1, 0, 0, 16), Text = "Clipboard API unavailable — select the text and press Ctrl+C.", TextColor3 = T.muted, TextSize = 11 })
        local close = styledButton(frame, "×", "default", maid)
        close.AnchorPoint = Vector2.new(1, 0)
        close.Position = UDim2.fromScale(1, 0)
        close.Size = UDim2.fromOffset(22, 18)
        maid:connect(close.Activated, function()
            Popup.close()
        end)
        local scroll = make("ScrollingFrame", {
            BackgroundColor3 = T.field,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, 40),
            Size = UDim2.new(1, 0, 1, -40),
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 4,
        }, frame)
        corner(scroll, 4)
        local box = make("TextBox", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            ClearTextOnFocus = false,
            MultiLine = true,
            TextEditable = true,
            Font = T.mono,
            Text = body,
            TextColor3 = T.text,
            TextSize = 11,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
        }, scroll)
        padding(box, 6, 6, 6, 6)
        return frame, maid
    end

    -- Copies text through the clipboard API, or shows a selectable viewer as fallback.
    function UI.copy(title, body)
        if Cap.copy(body) then
            Notify.push(title .. " copied to the clipboard.", "ok")
        else
            Popup.textViewer(title, body)
        end
    end

    function Popup.colorPicker(anchor, key, labelText)
        local frame, maid = Popup.open(Vector2.new(252, 216), anchor, false)
        local hue, saturation, value = Settings.get(key):ToHSV()
        local internal = false

        text(frame, { Position = UDim2.fromOffset(8, 6), Size = UDim2.fromOffset(200, 16), Text = labelText, Font = T.fontBold })
        local close = styledButton(frame, "×", "default", maid)
        close.Position = UDim2.fromOffset(226, 5)
        close.Size = UDim2.fromOffset(20, 18)
        maid:connect(close.Activated, function()
            Popup.close()
        end)

        local field = make("TextButton", { Position = UDim2.fromOffset(8, 28), Size = UDim2.fromOffset(160, 124), BorderSizePixel = 0, Text = "", AutoButtonColor = false }, frame)
        local whiteLayer = make("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0 }, field)
        make("UIGradient", { Transparency = NumberSequence.new(0, 1) }, whiteLayer)
        local blackLayer = make("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0 }, field)
        make("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(1, 0) }, blackLayer)
        local fieldCursor = make("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(9, 9), BackgroundTransparency = 1 }, field)
        corner(fieldCursor, 5)
        stroke(fieldCursor, Color3.new(1, 1, 1), 0, 2)

        local hueKeys = {}
        for index = 0, 6 do
            table.insert(hueKeys, ColorSequenceKeypoint.new(index / 6, Color3.fromHSV((index % 6) / 6, 1, 1)))
        end
        local hueBar = make("TextButton", { Position = UDim2.fromOffset(174, 28), Size = UDim2.fromOffset(14, 124), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Text = "", AutoButtonColor = false }, frame)
        make("UIGradient", { Rotation = 90, Color = ColorSequence.new(hueKeys) }, hueBar)
        local hueCursor = make("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(1, 4, 0, 3), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0 }, hueBar)
        stroke(hueCursor, Color3.new(0, 0, 0), 0.2)

        local newSwatch = make("Frame", { Position = UDim2.fromOffset(196, 28), Size = UDim2.fromOffset(48, 44), BorderSizePixel = 0 }, frame)
        corner(newSwatch, 4)
        local original = Settings.get(key)
        local oldSwatch = make("TextButton", { Position = UDim2.fromOffset(196, 76), Size = UDim2.fromOffset(48, 30), BackgroundColor3 = original, BorderSizePixel = 0, Text = "", AutoButtonColor = false }, frame)
        corner(oldSwatch, 4)
        text(frame, { Position = UDim2.fromOffset(196, 108), Size = UDim2.fromOffset(48, 14), Text = "new / old", TextSize = 9, TextColor3 = T.dim, TextXAlignment = Enum.TextXAlignment.Center })

        local function field3(x, width, placeholder)
            local box = make("TextBox", {
                Position = UDim2.fromOffset(x, 160),
                Size = UDim2.fromOffset(width, 20),
                BackgroundColor3 = T.field,
                BorderSizePixel = 0,
                ClearTextOnFocus = false,
                Font = T.mono,
                PlaceholderText = placeholder,
                PlaceholderColor3 = T.dim,
                Text = "",
                TextColor3 = T.text,
                TextSize = 11,
            }, frame)
            corner(box, 3)
            return box, stroke(box, T.lineSoft)
        end
        local redBox, redStroke = field3(8, 38, "R")
        local greenBox, greenStroke = field3(50, 38, "G")
        local blueBox, blueStroke = field3(92, 38, "B")
        local hexBox, hexStroke = field3(134, 110, "#RRGGBB")

        local function render()
            local current = Settings.get(key)
            field.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
            fieldCursor.Position = UDim2.fromScale(saturation, 1 - value)
            hueCursor.Position = UDim2.new(0.5, 0, hue, 0)
            newSwatch.BackgroundColor3 = current
            local channels = {
                { redBox, current.R },
                { greenBox, current.G },
                { blueBox, current.B },
            }
            for _, pair in ipairs(channels) do
                if not pair[1]:IsFocused() then
                    pair[1].Text = tostring(math.floor(pair[2] * 255 + 0.5))
                end
            end
            if not hexBox:IsFocused() then
                hexBox.Text = Util.toHex(current)
            end
        end

        local function syncFromColor(color)
            local h, s, v = color:ToHSV()
            if v > 0 then
                saturation = s
                if s > 0 then
                    hue = h
                end
            end
            value = v
        end

        local function commitHsv()
            internal = true
            Settings.set(key, Color3.fromHSV(hue, saturation, value))
            internal = false
            render()
        end

        local function commitColor(color)
            syncFromColor(color)
            internal = true
            Settings.set(key, color)
            internal = false
            render()
        end

        maid:give(Settings.on(key, function(color)
            if not internal then
                syncFromColor(color)
                render()
            end
        end))

        maid:connect(field.InputBegan, function(input)
            if not isPress(input) then
                return
            end
            local function update(position)
                if not field.Parent then
                    return
                end
                local origin, size = field.AbsolutePosition, field.AbsoluteSize
                saturation = math.clamp((position.X - origin.X) / math.max(size.X, 1), 0, 1)
                value = 1 - math.clamp((position.Y - origin.Y) / math.max(size.Y, 1), 0, 1)
                commitHsv()
            end
            UI.dragging = { owner = maid, update = update }
            update(input.Position)
        end)
        maid:connect(hueBar.InputBegan, function(input)
            if not isPress(input) then
                return
            end
            local function update(position)
                if not hueBar.Parent then
                    return
                end
                hue = math.clamp((position.Y - hueBar.AbsolutePosition.Y) / math.max(hueBar.AbsoluteSize.Y, 1), 0, 0.999)
                commitHsv()
            end
            UI.dragging = { owner = maid, update = update }
            update(input.Position)
        end)
        maid:connect(oldSwatch.Activated, function()
            commitColor(original)
        end)

        local function rgbHandler(box, boxStroke, channel)
            maid:connect(box.FocusLost, function()
                local number = tonumber(Util.trim(box.Text))
                if not number or number ~= math.floor(number) or number < 0 or number > 255 then
                    UI.flashError(boxStroke)
                    Notify.push(channel .. " must be a whole number from 0 to 255.", "warn")
                    render()
                    return
                end
                local current = Settings.get(key)
                local r, g, b = math.floor(current.R * 255 + 0.5), math.floor(current.G * 255 + 0.5), math.floor(current.B * 255 + 0.5)
                if channel == "Red" then
                    r = number
                elseif channel == "Green" then
                    g = number
                else
                    b = number
                end
                commitColor(Color3.fromRGB(r, g, b))
            end)
        end
        rgbHandler(redBox, redStroke, "Red")
        rgbHandler(greenBox, greenStroke, "Green")
        rgbHandler(blueBox, blueStroke, "Blue")
        maid:connect(hexBox.FocusLost, function()
            local color = Util.fromHex(hexBox.Text)
            if not color then
                UI.flashError(hexStroke)
                Notify.push("HEX must be #RRGGBB or RRGGBB (0-9, A-F).", "warn")
                render()
                return
            end
            commitColor(color)
        end)

        local function action(label, x, style, callback)
            local button = styledButton(frame, label, style, maid)
            button.Position = UDim2.fromOffset(x, 188)
            button.Size = UDim2.fromOffset(76, 20)
            maid:connect(button.Activated, callback)
        end
        action("Reset", 8, "default", function()
            Settings.reset(key)
        end)
        action("Copy HEX", 88, "default", function()
            local hex = Util.toHex(Settings.get(key))
            if Cap.copy(hex) then
                Notify.push("Copied " .. hex .. ".", "ok")
            else
                hexBox:CaptureFocus()
                hexBox.SelectionStart = 1
                hexBox.CursorPosition = #hexBox.Text + 1
                Notify.push("Clipboard unavailable. The HEX value is selected; press Ctrl+C.", "info")
            end
        end)
        action("Done", 168, "primary", function()
            Popup.close()
        end)
        render()
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/ui/notify.lua", factory = (function()
-- VEYL module: ui/notify
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local LIMITS = V.LIMITS
    local Log = V.Log
    local Notify = V.Notify
    local Settings = V.Settings
    local UI = V.UI
    local Session = V.Session
    local T = V.T
    local make = V.make
    local corner = V.corner
    local stroke = V.stroke
    local padding = V.padding
    local text = V.text

    ----------------------------------------------------------------------------
    -- 18. Notifications (bounded toast stack)
    ----------------------------------------------------------------------------

    Notify.serial = 0
    local TOAST_COLORS = { info = T.accent, ok = T.ok, warn = T.warn, error = T.bad }

    function Notify.push(message, kind)
        kind = kind or "info"
        message = tostring(message)
        if kind == "warn" or kind == "error" then
            Log.add(kind, message)
        end
        local holder = UI.toastHolder
        if not holder or not holder.Parent or not Session.alive then
            if kind ~= "warn" and kind ~= "error" then
                print("[VEYL] " .. message)
            end
            return
        end
        if (kind == "info" or kind == "ok") and not Settings.get("ui.toasts") then
            return
        end
        Notify.serial += 1
        local toast = make("Frame", {
            BackgroundColor3 = T.raised,
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            LayoutOrder = Notify.serial,
        })
        corner(toast, 6)
        stroke(toast, T.line)
        make("Frame", { BackgroundColor3 = TOAST_COLORS[kind] or T.accent, BorderSizePixel = 0, Position = UDim2.fromOffset(6, 7), Size = UDim2.new(0, 3, 1, -14) }, toast)
        local label = text(toast, {
            Position = UDim2.fromOffset(16, 0),
            Size = UDim2.new(1, -24, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            Text = message,
            TextWrapped = true,
            TextTruncate = Enum.TextTruncate.None,
        })
        padding(label, 0, 0, 7, 7)
        toast.Parent = holder
        local toasts = {}
        for _, child in ipairs(holder:GetChildren()) do
            if child:IsA("Frame") then
                table.insert(toasts, child)
            end
        end
        table.sort(toasts, function(a, b)
            return a.LayoutOrder < b.LayoutOrder
        end)
        for index = 1, #toasts - LIMITS.toasts do
            toasts[index]:Destroy()
        end
        task.delay(kind == "error" and 6 or 3.5, function()
            if toast.Parent then
                toast:Destroy()
            end
        end)
    end

    V.TOAST_COLORS = TOAST_COLORS
end
end)() }
MODULES[#MODULES + 1] = { path = "src/overlay.lua", factory = (function()
-- VEYL module: overlay
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local PlayerGui = V.PlayerGui
    local NAMES = V.NAMES
    local Util = V.Util
    local Cap = V.Cap
    local Settings = V.Settings
    local UI = V.UI
    local Overlay = V.Overlay
    local T = V.T
    local make = V.make
    local stroke = V.stroke

    ----------------------------------------------------------------------------
    -- 12a. Overlay renderer: Drawing API when available, ScreenGui fallback
    --      Both use viewport coordinates (WorldToViewportPoint, GUI inset ignored).
    ----------------------------------------------------------------------------

    Overlay.registry = {}
    Overlay.mode = nil
    Overlay.reset = Util.signal()

    local NullPrim = {}
    NullPrim.__index = NullPrim
    function NullPrim:hide() end
    function NullPrim:line() end
    function NullPrim:rect() end
    function NullPrim:text() end
    function NullPrim:circle() end
    function NullPrim:triangle() end
    function NullPrim:Destroy() end

    local DrawPrim = {}
    DrawPrim.__index = DrawPrim

    local DRAW_DEFAULTS = {
        Line = { Thickness = 1 },
        Square = { Thickness = 1, Filled = false },
        Text = { Center = true, Outline = true, Size = 13 },
        Circle = { Thickness = 1, NumSides = 48, Filled = false },
        Triangle = { Thickness = 1, Filled = true },
    }

    local function newDrawPrim(kind)
        local ok, object = pcall(Cap.drawingNew, kind)
        if not ok or object == nil then
            return nil
        end
        pcall(function()
            object.Visible = false
        end)
        for property, value in pairs(DRAW_DEFAULTS[kind]) do
            pcall(function()
                object[property] = value
            end)
        end
        if kind == "Text" and Cap.drawingFont ~= nil then
            pcall(function()
                object.Font = Cap.drawingFont
            end)
        end
        local prim = setmetatable({ object = object, shown = false }, DrawPrim)
        Overlay.registry[prim] = true
        return prim
    end

    function DrawPrim:hide()
        if self.shown then
            self.shown = false
            self.object.Visible = false
        end
    end

    function DrawPrim:show()
        if not self.shown then
            self.shown = true
            self.object.Visible = true
        end
    end

    -- Drawing "Transparency" is opacity on common runtimes (1 = fully visible).
    function DrawPrim:line(from, to, color, thickness, opacity)
        local object = self.object
        object.From = from
        object.To = to
        object.Color = color
        object.Thickness = thickness
        object.Transparency = opacity
        self:show()
    end

    function DrawPrim:rect(position, size, color, thickness, opacity, filled)
        local object = self.object
        object.Position = position
        object.Size = size
        object.Color = color
        object.Thickness = thickness
        object.Transparency = opacity
        object.Filled = filled == true
        self:show()
    end

    function DrawPrim:text(value, position, color, size, opacity)
        local object = self.object
        object.Text = value
        object.Position = position
        object.Color = color
        object.Size = size
        object.Transparency = opacity
        self:show()
    end

    function DrawPrim:circle(center, radius, color, thickness, opacity)
        local object = self.object
        object.Position = center
        object.Radius = radius
        object.Color = color
        object.Thickness = thickness
        object.Transparency = opacity
        self:show()
    end

    function DrawPrim:triangle(a, b, c, color, opacity)
        local object = self.object
        object.PointA = a
        object.PointB = b
        object.PointC = c
        object.Color = color
        object.Transparency = opacity
        self:show()
    end

    function DrawPrim:Destroy()
        Overlay.registry[self] = nil
        local object = self.object
        self.object = nil
        if object ~= nil then
            pcall(function()
                object:Remove()
            end)
        end
    end

    local GuiPrim = {}
    GuiPrim.__index = GuiPrim

    function Overlay.guiRoot()
        if Overlay.gui and Overlay.gui.Parent then
            return Overlay.gui
        end
        local gui = make("ScreenGui", {
            Name = NAMES.overlay,
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            DisplayOrder = 90,
        })
        gui:SetAttribute(NAMES.owned, true)
        gui.Parent = (UI.gui and UI.gui.Parent) or PlayerGui
        Overlay.gui = gui
        return gui
    end

    local function newGuiPrim(kind)
        local root = Overlay.guiRoot()
        local object, outline
        if kind == "Line" then
            object = make("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, Visible = false }, root)
        elseif kind == "Square" then
            object = make("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false }, root)
            outline = stroke(object, Color3.new(1, 1, 1))
        elseif kind == "Text" then
            object = make("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(260, 16),
                Font = T.fontMedium,
                TextStrokeColor3 = Color3.new(0, 0, 0),
                TextStrokeTransparency = 0.35,
                Visible = false,
            }, root)
        elseif kind == "Circle" then
            object = make("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false }, root)
            make("UICorner", { CornerRadius = UDim.new(0.5, 0) }, object)
            outline = stroke(object, Color3.new(1, 1, 1))
        else
            object = make("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Text = "▲",
                Font = T.fontBold,
                Visible = false,
            }, root)
        end
        local prim = setmetatable({ object = object, outline = outline, shown = false }, GuiPrim)
        Overlay.registry[prim] = true
        return prim
    end

    GuiPrim.hide = DrawPrim.hide
    GuiPrim.show = DrawPrim.show

    function GuiPrim:line(from, to, color, thickness, opacity)
        local object = self.object
        local delta = to - from
        object.Position = UDim2.fromOffset((from.X + to.X) / 2, (from.Y + to.Y) / 2)
        object.Size = UDim2.fromOffset(delta.Magnitude, thickness)
        object.Rotation = math.deg(math.atan2(delta.Y, delta.X))
        object.BackgroundColor3 = color
        object.BackgroundTransparency = 1 - opacity
        self:show()
    end

    function GuiPrim:rect(position, size, color, thickness, opacity, filled)
        local object, outline = self.object, self.outline
        object.Position = UDim2.fromOffset(position.X, position.Y)
        object.Size = UDim2.fromOffset(size.X, size.Y)
        if filled then
            object.BackgroundColor3 = color
            object.BackgroundTransparency = 1 - opacity
            outline.Enabled = false
        else
            object.BackgroundTransparency = 1
            outline.Enabled = true
            outline.Color = color
            outline.Thickness = thickness
            outline.Transparency = 1 - opacity
        end
        self:show()
    end

    function GuiPrim:text(value, position, color, size, opacity)
        local object = self.object
        object.Text = value
        object.Position = UDim2.fromOffset(position.X, position.Y)
        object.Size = UDim2.fromOffset(260, size + 4)
        object.TextColor3 = color
        object.TextSize = size
        object.TextTransparency = 1 - opacity
        self:show()
    end

    function GuiPrim:circle(center, radius, color, thickness, opacity)
        local object, outline = self.object, self.outline
        object.Position = UDim2.fromOffset(center.X, center.Y)
        object.Size = UDim2.fromOffset(radius * 2, radius * 2)
        outline.Color = color
        outline.Thickness = thickness
        outline.Transparency = 1 - opacity
        self:show()
    end

    function GuiPrim:triangle(a, b, c, color, opacity)
        local object = self.object
        local base = (b + c) / 2
        local direction = a - base
        local length = math.max(direction.Magnitude, 1)
        object.Position = UDim2.fromOffset((a.X + base.X) / 2, (a.Y + base.Y) / 2)
        object.Size = UDim2.fromOffset(length * 2, length * 2)
        object.Rotation = math.deg(math.atan2(direction.Y, direction.X)) + 90
        object.TextSize = math.max(8, math.floor(length * 1.5))
        object.TextColor3 = color
        object.TextTransparency = 1 - opacity
        self:show()
    end

    function GuiPrim:Destroy()
        Overlay.registry[self] = nil
        if self.object then
            self.object:Destroy()
            self.object = nil
        end
    end

    function Overlay.resolveMode()
        if Settings.get("esp.renderer") ~= "GUI" and Cap.drawingNew then
            return "Drawing"
        end
        return "GUI"
    end

    function Overlay.modeText()
        local preference = Settings.get("esp.renderer")
        local mode = Overlay.mode or Overlay.resolveMode()
        if preference == "Drawing" and mode ~= "Drawing" then
            return "GUI (Drawing unavailable)", T.warn
        end
        if mode == "GUI" and preference == "Auto" then
            return "GUI fallback", T.warn
        end
        return mode, T.ok
    end

    function Overlay.clearAll()
        for prim in pairs(Overlay.registry) do
            prim:Destroy()
        end
        table.clear(Overlay.registry)
        if Overlay.gui then
            Overlay.gui:Destroy()
            Overlay.gui = nil
        end
    end

    function Overlay.ensureMode()
        local mode = Overlay.resolveMode()
        if mode ~= Overlay.mode then
            Overlay.clearAll()
            Overlay.mode = mode
            Overlay.reset:Fire(mode)
        end
    end

    function Overlay.new(kind)
        if not Overlay.mode then
            Overlay.mode = Overlay.resolveMode()
        end
        if Overlay.mode == "Drawing" then
            return newDrawPrim(kind) or setmetatable({}, NullPrim)
        end
        return newGuiPrim(kind)
    end

    V.NullPrim = NullPrim
    V.DrawPrim = DrawPrim
    V.DRAW_DEFAULTS = DRAW_DEFAULTS
    V.newDrawPrim = newDrawPrim
    V.GuiPrim = GuiPrim
    V.newGuiPrim = newGuiPrim
end
end)() }
MODULES[#MODULES + 1] = { path = "src/entities.lua", factory = (function()
-- VEYL module: entities
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Players = V.Players
    local CollectionService = V.CollectionService
    local Workspace = V.Workspace
    local LocalPlayer = V.LocalPlayer
    local NAMES = V.NAMES
    local LIMITS = V.LIMITS
    local Util = V.Util
    local Log = V.Log
    local Entities = V.Entities
    local App = V.App
    local Session = V.Session
    local Maid = V.Maid

    ----------------------------------------------------------------------------
    -- 10. Entity discovery (event-driven, live Workspace models only)
    ----------------------------------------------------------------------------

    Entities.byModel = {}
    Entities.count = 0
    Entities.npcCount = 0
    Entities.allow = {}
    Entities.playerMaids = {}
    Entities.added = Util.signal()
    Entities.removed = Util.signal()
    Entities.changed = Util.signal()
    Entities.maid = Maid.new()
    Entities.nextId = 0
    Entities.scanToken = 0

    local KIND_SHORT = { ["Test target"] = "Test", Player = "Player", NPC = "NPC" }

    local function entityKind(model)
        local player = Players:GetPlayerFromCharacter(model)
        -- Live Player characters remain Players even if tagged as test targets.
        -- Tags must never bypass the explicit per-session player allowlist.
        if player then
            return "Player", player
        end
        if CollectionService:HasTag(model, NAMES.tag) then
            return "Test target", nil
        end
        return "NPC", nil
    end

    local function entityName(entity)
        local model = entity.model
        if entity.kind == "Test target" then
            local label = model:GetAttribute(NAMES.targetLabel)
            if type(label) == "string" and label ~= "" then
                return Util.truncate(label, 40)
            end
        end
        local player = entity.player
        if player then
            if player.DisplayName ~= player.Name then
                return player.DisplayName .. " (@" .. player.Name .. ")"
            end
            return player.Name
        end
        return model.Name
    end

    function Entities.track(model)
        if not Session.alive or typeof(model) ~= "Instance" or not model:IsA("Model") then
            return
        end
        local existing = Entities.byModel[model]
        if existing then
            Entities.refreshKind(existing)
            return
        end
        if model == LocalPlayer.Character or not model:IsDescendantOf(Workspace) then
            return
        end
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end
        local kind, player = entityKind(model)
        if player == LocalPlayer then
            return
        end
        if kind == "NPC" and Entities.npcCount >= LIMITS.npcs then
            if not Entities.npcLimitLogged then
                Entities.npcLimitLogged = true
                Log.add("warn", "NPC registry limit (" .. LIMITS.npcs .. ") reached; further NPC models are not tracked.")
            end
            return
        end
        Entities.nextId += 1
        local entity = {
            id = Entities.nextId,
            model = model,
            humanoid = humanoid,
            kind = kind,
            player = player,
            maid = Maid.new(),
            rootRetry = 0,
            bbAt = 0,
            visAt = 0,
        }
        entity.name = entityName(entity)
        entity.maid:connect(model.AncestryChanged, function()
            if not model:IsDescendantOf(Workspace) then
                Entities.untrack(model, "removed from Workspace")
            end
        end)
        entity.maid:connect(humanoid.AncestryChanged, function(_, parent)
            if parent ~= model then
                local replacement = model:FindFirstChildOfClass("Humanoid")
                if replacement then
                    entity.humanoid = replacement
                else
                    Entities.untrack(model, "Humanoid removed")
                end
            end
        end)
        Entities.byModel[model] = entity
        Entities.count += 1
        if kind == "NPC" then
            Entities.npcCount += 1
        end
        Entities.added:Fire(entity)
    end

    function Entities.untrack(model, reason)
        local entity = Entities.byModel[model]
        if not entity then
            return
        end
        Entities.byModel[model] = nil
        Entities.count -= 1
        if entity.kind == "NPC" then
            Entities.npcCount -= 1
        end
        entity.removed = true
        entity.maid:clean()
        Entities.removed:Fire(entity, reason)
    end

    function Entities.refreshKind(entity)
        local kind, player = entityKind(entity.model)
        if player == LocalPlayer then
            Entities.untrack(entity.model, "local character")
            return
        end
        if kind ~= entity.kind or player ~= entity.player then
            if entity.kind == "NPC" then
                Entities.npcCount -= 1
            end
            if kind == "NPC" then
                Entities.npcCount += 1
            end
            entity.kind = kind
            entity.player = player
            entity.name = entityName(entity)
            Entities.changed:Fire(entity)
        end
    end

    function Entities.getRoot(entity)
        local root = entity.root
        if root and root.Parent then
            return root
        end
        local now = os.clock()
        if now < entity.rootRetry then
            return nil
        end
        local model, humanoid = entity.model, entity.humanoid
        root = humanoid and humanoid.RootPart
        if not (root and root.Parent) then
            root = model:FindFirstChild("HumanoidRootPart")
            if not (root and root:IsA("BasePart")) then
                root = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
            end
        end
        entity.root = root
        if not root then
            entity.rootRetry = now + 0.5
        end
        return root
    end

    function Entities.isAlive(entity)
        local humanoid = entity.humanoid
        return humanoid ~= nil and humanoid.Parent ~= nil and humanoid.Health > 0
    end

    function Entities.isAllowed(entity)
        return entity.player ~= nil and Entities.allow[entity.player.UserId] == true
    end

    function Entities.setAllowed(entity, allowed)
        if not entity.player then
            return
        end
        Entities.allow[entity.player.UserId] = allowed or nil
        Log.add("info", (allowed and "Allowlisted " or "Removed from allowlist: ") .. entity.name)
        Entities.changed:Fire(entity)
    end

    function Entities.part(entity, which)
        local model = entity.model
        if which == "Head" then
            local head = model:FindFirstChild("Head")
            if head and head:IsA("BasePart") then
                return head
            end
        elseif which == "Torso" then
            local torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
            if torso and torso:IsA("BasePart") then
                return torso
            end
        end
        return Entities.getRoot(entity)
    end

    -- Cached bounding box relative to the root, refreshed at most once per second.
    function Entities.bounds(entity, root, now)
        if not entity.bbOffset or now - entity.bbAt > 1 then
            entity.bbAt = now
            local ok, boxCFrame, size = pcall(entity.model.GetBoundingBox, entity.model)
            if ok and size.Magnitude > 0.5 and size.Magnitude < 60 then
                entity.bbOffset = root.CFrame:ToObjectSpace(boxCFrame)
                entity.bbSize = size
            else
                entity.bbOffset = CFrame.new(0, -0.5, 0)
                entity.bbSize = Vector3.new(4, 5.5, 2)
            end
        end
        return root.CFrame * entity.bbOffset, entity.bbSize
    end

    local losParams = RaycastParams.new()
    losParams.FilterType = Enum.RaycastFilterType.Exclude
    losParams.IgnoreWater = true

    function Entities.lineOfSight(entity, part, origin)
        local filter = { entity.model }
        local character = LocalPlayer.Character
        if character then
            table.insert(filter, character)
        end
        local camera = Workspace.CurrentCamera
        if camera then
            table.insert(filter, camera)
        end
        if App.fxFolder and App.fxFolder.Parent then
            table.insert(filter, App.fxFolder)
        end
        losParams.FilterDescendantsInstances = filter
        return Workspace:Raycast(origin, part.Position - origin, losParams) == nil
    end

    -- Visibility is cached per entity and limited by a per-frame raycast budget.
    function Entities.visibility(entity, part, origin, budget, now)
        if entity.visible ~= nil and now - entity.visAt < 0.15 then
            return entity.visible
        end
        if budget.left <= 0 then
            return entity.visible
        end
        budget.left -= 1
        entity.visible = Entities.lineOfSight(entity, part, origin)
        entity.visAt = now
        return entity.visible
    end

    function Entities.considerHumanoid(humanoid)
        local model = humanoid.Parent
        if model and model:IsA("Model") then
            Entities.track(model)
        end
    end

    function Entities.watchPlayer(player)
        if player == LocalPlayer or Entities.playerMaids[player] then
            return
        end
        local maid = Maid.new()
        Entities.playerMaids[player] = maid
        maid:connect(player.CharacterAdded, function(character)
            task.defer(function()
                if Session.alive then
                    Entities.track(character)
                end
            end)
        end)
        maid:connect(player.CharacterRemoving, function(character)
            Entities.untrack(character, "character removing")
        end)
        if player.Character then
            Entities.track(player.Character)
        end
    end

    function Entities.scan()
        Entities.scanToken += 1
        local token = Entities.scanToken
        Entities.scanning = true
        task.spawn(function()
            local descendants = Workspace:GetDescendants()
            for index, instance in ipairs(descendants) do
                if not Session.alive or token ~= Entities.scanToken then
                    return
                end
                if instance.ClassName == "Humanoid" then
                    Entities.considerHumanoid(instance)
                end
                if index % 4000 == 0 then
                    task.wait()
                end
            end
            for _, instance in ipairs(CollectionService:GetTagged(NAMES.tag)) do
                Entities.track(instance)
            end
            if token == Entities.scanToken then
                Entities.scanning = false
            end
        end)
    end

    function Entities.start()
        local maid = Entities.maid
        maid:connect(Players.PlayerAdded, Entities.watchPlayer)
        maid:connect(Players.PlayerRemoving, function(player)
            local playerMaid = Entities.playerMaids[player]
            if playerMaid then
                playerMaid:clean()
                Entities.playerMaids[player] = nil
            end
            Entities.allow[player.UserId] = nil
        end)
        for _, player in ipairs(Players:GetPlayers()) do
            Entities.watchPlayer(player)
        end
        maid:connect(Workspace.DescendantAdded, function(instance)
            if instance.ClassName == "Humanoid" then
                task.defer(function()
                    if Session.alive and instance.Parent then
                        Entities.considerHumanoid(instance)
                    end
                end)
            end
        end)
        maid:connect(CollectionService:GetInstanceAddedSignal(NAMES.tag), function(instance)
            local entity = Entities.byModel[instance]
            if entity then
                Entities.refreshKind(entity)
            else
                Entities.track(instance)
            end
            Log.add("info", "Test target tag added: " .. instance.Name)
        end)
        maid:connect(CollectionService:GetInstanceRemovedSignal(NAMES.tag), function(instance)
            local entity = Entities.byModel[instance]
            if entity then
                Entities.refreshKind(entity)
            end
        end)
        maid:connect(LocalPlayer.CharacterAdded, function(character)
            if Entities.byModel[character] then
                Entities.untrack(character, "local character")
            end
        end)
        Entities.scan()
    end

    function Entities.rebuild()
        for model in pairs(Entities.byModel) do
            Entities.untrack(model, "registry rebuild")
        end
        Entities.npcLimitLogged = false
        for player, playerMaid in pairs(Entities.playerMaids) do
            playerMaid:clean()
            Entities.playerMaids[player] = nil
        end
        for _, player in ipairs(Players:GetPlayers()) do
            Entities.watchPlayer(player)
        end
        Entities.scan()
        Log.add("info", "Entity registry rebuilt.")
    end

    function Entities.stop()
        Entities.scanToken += 1
        Entities.maid:clean()
        for player, playerMaid in pairs(Entities.playerMaids) do
            playerMaid:clean()
            Entities.playerMaids[player] = nil
        end
        for model in pairs(Entities.byModel) do
            Entities.untrack(model, "shutdown")
        end
    end

    V.KIND_SHORT = KIND_SHORT
    V.entityKind = entityKind
    V.entityName = entityName
    V.losParams = losParams
end
end)() }
MODULES[#MODULES + 1] = { path = "src/esp.lua", factory = (function()
-- VEYL module: esp
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local RunService = V.RunService
    local UserInputService = V.UserInputService
    local Workspace = V.Workspace
    local NAMES = V.NAMES
    local LIMITS = V.LIMITS
    local Util = V.Util
    local Log = V.Log
    local Settings = V.Settings
    local Overlay = V.Overlay
    local Entities = V.Entities
    local ESP = V.ESP
    local App = V.App
    local Maid = V.Maid
    local make = V.make
    local KIND_SHORT = V.KIND_SHORT

    ----------------------------------------------------------------------------
    -- 12b. ESP / Visuals
    ----------------------------------------------------------------------------

    ESP.visuals = {}
    ESP.highlights = {}
    ESP.drawn = 0

    local VISUAL_PARTS = { "boxOutline", "box", "name", "info", "healthBack", "healthFill", "tracer", "arrow" }
    local VISUAL_KINDS = {
        boxOutline = "Square",
        box = "Square",
        name = "Text",
        info = "Text",
        healthBack = "Square",
        healthFill = "Square",
        tracer = "Line",
        arrow = "Triangle",
    }
    local BLACK = Color3.new(0, 0, 0)
    local LOW_HEALTH = Color3.fromRGB(255, 80, 80)

    local function newVisual()
        local visual = {}
        for _, key in ipairs(VISUAL_PARTS) do
            visual[key] = Overlay.new(VISUAL_KINDS[key])
        end
        return visual
    end

    local function hideVisual(visual, except)
        for _, key in ipairs(VISUAL_PARTS) do
            if key ~= except then
                visual[key]:hide()
            end
        end
    end

    local function destroyVisual(visual)
        for _, key in ipairs(VISUAL_PARTS) do
            visual[key]:Destroy()
        end
    end

    function ESP.eligible(entity)
        if entity.kind == "Test target" then
            return Settings.get("esp.showTargets")
        elseif entity.kind == "NPC" then
            return Settings.get("esp.showNpcs")
        elseif entity.kind == "Player" then
            return Settings.get("esp.showPlayers") and Entities.isAllowed(entity)
        end
        return false
    end

    local function kindColor(entity, values)
        if entity.kind == "Player" then
            return values["color.player"]
        elseif entity.kind == "Test target" then
            return values["color.testTarget"]
        end
        return values["color.npc"]
    end

    -- Precedence: visibility colors > entity-type colors > the element's own color.
    local function elementColor(entity, key, values)
        if values["esp.visColors"] and values["esp.visibility"] and entity.visible ~= nil then
            return entity.visible and values["color.visible"] or values["color.occluded"]
        end
        if values["esp.typeColors"] then
            return kindColor(entity, values)
        end
        return values[key]
    end

    local CORNERS = {}
    for index = 0, 7 do
        CORNERS[index + 1] = Vector3.new(
            index % 2 == 0 and -0.5 or 0.5,
            math.floor(index / 2) % 2 == 0 and -0.5 or 0.5,
            math.floor(index / 4) % 2 == 0 and -0.5 or 0.5
        )
    end
    local EDGES = {}
    for index = 0, 7 do
        for _, bit in ipairs({ 1, 2, 4 }) do
            if bit32.band(index, bit) == 0 then
                table.insert(EDGES, { index + 1, index + bit + 1 })
            end
        end
    end
    local cornerWorld, cornerDepth = {}, {}
    local NEAR_DEPTH = 0.5

    -- Projects an oriented box; edges that cross the near plane are clipped instead
    -- of discarding the whole box when one corner is behind the camera.
    local function projectBox(camera, cameraCFrame, boxCFrame, size)
        local origin, look = cameraCFrame.Position, cameraCFrame.LookVector
        local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
        local any = false
        local function add(point)
            local screen = camera:WorldToViewportPoint(point)
            if screen.X < minX then
                minX = screen.X
            end
            if screen.X > maxX then
                maxX = screen.X
            end
            if screen.Y < minY then
                minY = screen.Y
            end
            if screen.Y > maxY then
                maxY = screen.Y
            end
            any = true
        end
        for index = 1, 8 do
            local world = boxCFrame:PointToWorldSpace(CORNERS[index] * size)
            cornerWorld[index] = world
            cornerDepth[index] = (world - origin):Dot(look)
        end
        for index = 1, 8 do
            if cornerDepth[index] >= NEAR_DEPTH then
                add(cornerWorld[index])
            end
        end
        for _, edge in ipairs(EDGES) do
            local a, b = edge[1], edge[2]
            local depthA, depthB = cornerDepth[a], cornerDepth[b]
            if (depthA >= NEAR_DEPTH) ~= (depthB >= NEAR_DEPTH) then
                add(cornerWorld[a]:Lerp(cornerWorld[b], (NEAR_DEPTH - depthA) / (depthB - depthA)))
            end
        end
        return any, minX, minY, maxX, maxY
    end

    local function drawArrow(visual, cameraCFrame, position, viewport, color)
        local relative = cameraCFrame:PointToObjectSpace(position)
        local direction = Vector2.new(relative.X, -relative.Y)
        if direction.Magnitude < 1e-3 then
            direction = Vector2.new(0, 1)
        end
        direction = direction.Unit
        local half = viewport / 2
        local reachX = math.max(half.X - 48, 10) / math.max(math.abs(direction.X), 1e-3)
        local reachY = math.max(half.Y - 48, 10) / math.max(math.abs(direction.Y), 1e-3)
        local center = half + direction * math.min(reachX, reachY)
        local side = Vector2.new(-direction.Y, direction.X) * 7
        local back = center - direction * 6
        visual.arrow:triangle(center + direction * 10, back + side, back - side, color, 0.9)
    end

    local espBudget = { left = 0 }

    local function drawEntity(entity, visual, camera, cameraCFrame, viewport, now, tracerFrom, values)
        local root = Entities.getRoot(entity)
        local humanoid = entity.humanoid
        if not root or not humanoid or humanoid.Health <= 0 then
            hideVisual(visual)
            return false
        end
        local origin = cameraCFrame.Position
        local distance = (root.Position - origin).Magnitude
        if distance > values["esp.maxDistance"] then
            hideVisual(visual)
            return false
        end
        if values["esp.visibility"] then
            Entities.visibility(entity, root, origin, espBudget, now)
        end
        local boxCFrame, size = Entities.bounds(entity, root, now)
        local inFront, minX, minY, maxX, maxY = projectBox(camera, cameraCFrame, boxCFrame, size)
        local onScreen = inFront and maxX >= 0 and minX <= viewport.X and maxY >= 0 and minY <= viewport.Y
        if not onScreen then
            hideVisual(visual, "arrow")
            if values["esp.offscreen"] then
                drawArrow(visual, cameraCFrame, root.Position, viewport, elementColor(entity, "color.box", values))
            else
                visual.arrow:hide()
            end
            return true
        end
        visual.arrow:hide()
        if maxX - minX < 4 then
            local middle = (minX + maxX) / 2
            minX, maxX = middle - 2, middle + 2
        end
        if maxY - minY < 4 then
            local middle = (minY + maxY) / 2
            minY, maxY = middle - 2, middle + 2
        end
        local boxPosition = Vector2.new(minX, minY)
        local boxSize = Vector2.new(maxX - minX, maxY - minY)
        local centerX = (minX + maxX) / 2
        local textSize = values["esp.textSize"]

        if values["esp.boxes"] then
            local opacity = 1 - values["esp.boxTransparency"] / 100
            visual.boxOutline:rect(boxPosition - Vector2.new(1, 1), boxSize + Vector2.new(2, 2), BLACK, 3, opacity * 0.6, false)
            visual.box:rect(boxPosition, boxSize, elementColor(entity, "color.box", values), 1, opacity, false)
        else
            visual.boxOutline:hide()
            visual.box:hide()
        end
        if values["esp.names"] then
            visual.name:text(entity.name, Vector2.new(centerX, minY - textSize - 3), values["color.name"], textSize, 1)
        else
            visual.name:hide()
        end
        if values["esp.distance"] then
            local status = ""
            if values["esp.visibility"] and entity.visible ~= nil then
                status = entity.visible and " · visible" or " · occluded"
            end
            visual.info:text(
                string.format("%s · %d st%s", KIND_SHORT[entity.kind] or "?", math.floor(distance + 0.5), status),
                Vector2.new(centerX, maxY + 2),
                values["color.name"],
                math.max(10, textSize - 2),
                0.9
            )
        else
            visual.info:hide()
        end
        if values["esp.health"] then
            local maxHealth = humanoid.MaxHealth
            local fraction = maxHealth > 0 and math.clamp(humanoid.Health / maxHealth, 0, 1) or 0
            local fillHeight = math.max(1, boxSize.Y * fraction)
            visual.healthBack:rect(Vector2.new(minX - 7, minY - 1), Vector2.new(4, boxSize.Y + 2), BLACK, 1, 0.6, true)
            visual.healthFill:rect(Vector2.new(minX - 6, maxY - fillHeight), Vector2.new(2, fillHeight), values["color.health"]:Lerp(LOW_HEALTH, 1 - fraction), 1, 1, true)
        else
            visual.healthBack:hide()
            visual.healthFill:hide()
        end
        if values["esp.tracers"] then
            visual.tracer:line(tracerFrom, Vector2.new(centerX, maxY), elementColor(entity, "color.tracer", values), 1, 1 - values["esp.tracerTransparency"] / 100)
        else
            visual.tracer:hide()
        end
        return true
    end

    function ESP.step()
        local camera = Workspace.CurrentCamera
        if not camera then
            return
        end
        local values = Settings.values
        local cameraCFrame = camera.CFrame
        local viewport = camera.ViewportSize
        local now = os.clock()
        espBudget.left = 10
        local origin = values["esp.tracerOrigin"]
        local tracerFrom
        if origin == "Center" then
            tracerFrom = viewport / 2
        elseif origin == "Mouse" then
            tracerFrom = UserInputService:GetMouseLocation()
        else
            tracerFrom = Vector2.new(viewport.X / 2, viewport.Y - 2)
        end
        local drawn = 0
        for _, entity in pairs(Entities.byModel) do
            local visual = ESP.visuals[entity]
            if not entity.espBroken and ESP.eligible(entity) then
                if not visual then
                    visual = newVisual()
                    ESP.visuals[entity] = visual
                end
                local ok, result = pcall(drawEntity, entity, visual, camera, cameraCFrame, viewport, now, tracerFrom, values)
                if ok then
                    if result then
                        drawn += 1
                    end
                else
                    hideVisual(visual)
                    entity.espFails = (entity.espFails or 0) + 1
                    if entity.espFails >= 10 then
                        entity.espBroken = true
                        Log.add("warn", "ESP skips " .. entity.name .. " after repeated errors: " .. tostring(result))
                    end
                end
            elseif visual then
                hideVisual(visual)
            end
        end
        ESP.drawn = drawn
    end

    function ESP.updateHighlights()
        local values = Settings.values
        local camera = Workspace.CurrentCamera
        if not values["esp.enabled"] or not values["esp.highlight"] or not camera then
            for entity, highlight in pairs(ESP.highlights) do
                highlight:Destroy()
                ESP.highlights[entity] = nil
            end
            return
        end
        local origin = camera.CFrame.Position
        local candidates = {}
        for _, entity in pairs(Entities.byModel) do
            if ESP.eligible(entity) and Entities.isAlive(entity) then
                local root = Entities.getRoot(entity)
                if root then
                    local distance = (root.Position - origin).Magnitude
                    if distance <= values["esp.maxDistance"] then
                        table.insert(candidates, { entity = entity, distance = distance })
                    end
                end
            end
        end
        table.sort(candidates, function(a, b)
            return a.distance < b.distance
        end)
        local keep = {}
        local depth = values["esp.hlDepth"] == "Always on top" and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
        for index = 1, math.min(#candidates, LIMITS.highlights) do
            local entity = candidates[index].entity
            keep[entity] = true
            local highlight = ESP.highlights[entity]
            if not highlight or not highlight.Parent then
                highlight = make("Highlight", { Name = "VEYLHighlight", Adornee = entity.model })
                highlight:SetAttribute(NAMES.owned, true)
                highlight.Parent = App.fx()
                ESP.highlights[entity] = highlight
            end
            highlight.FillColor = values["esp.typeColors"] and kindColor(entity, values) or values["color.hlFill"]
            highlight.OutlineColor = values["color.hlOutline"]
            highlight.FillTransparency = values["esp.hlFillTransparency"] / 100
            highlight.OutlineTransparency = values["esp.hlOutlineTransparency"] / 100
            highlight.DepthMode = depth
        end
        for entity, highlight in pairs(ESP.highlights) do
            if not keep[entity] then
                highlight:Destroy()
                ESP.highlights[entity] = nil
            end
        end
    end

    function ESP.dropVisuals()
        for entity, visual in pairs(ESP.visuals) do
            destroyVisual(visual)
            ESP.visuals[entity] = nil
        end
    end

    function ESP.start()
        if ESP.maid then
            return
        end
        Overlay.ensureMode()
        local maid = Maid.new()
        ESP.maid = maid
        maid:connect(RunService.RenderStepped, Util.guardStep("ESP", ESP.step, function()
            Settings.set("esp.enabled", false)
        end))
        local elapsed = 0
        maid:connect(RunService.Heartbeat, function(deltaTime)
            elapsed += deltaTime
            if elapsed >= 0.5 then
                elapsed = 0
                local ok, err = pcall(ESP.updateHighlights)
                if not ok then
                    Log.add("warn", "Highlight update failed: " .. tostring(err))
                end
            end
        end)
        ESP.updateHighlights()
        Log.add("info", "ESP started with the " .. tostring(Overlay.mode) .. " renderer.")
    end

    function ESP.stop()
        if ESP.maid then
            ESP.maid:clean()
            ESP.maid = nil
        end
        ESP.dropVisuals()
        for entity, highlight in pairs(ESP.highlights) do
            highlight:Destroy()
            ESP.highlights[entity] = nil
        end
        ESP.drawn = 0
    end

    function ESP.forget(entity)
        local visual = ESP.visuals[entity]
        if visual then
            destroyVisual(visual)
            ESP.visuals[entity] = nil
        end
        local highlight = ESP.highlights[entity]
        if highlight then
            highlight:Destroy()
            ESP.highlights[entity] = nil
        end
    end

    V.VISUAL_PARTS = VISUAL_PARTS
    V.VISUAL_KINDS = VISUAL_KINDS
    V.BLACK = BLACK
    V.LOW_HEALTH = LOW_HEALTH
    V.newVisual = newVisual
    V.hideVisual = hideVisual
    V.destroyVisual = destroyVisual
    V.kindColor = kindColor
    V.elementColor = elementColor
    V.CORNERS = CORNERS
    V.EDGES = EDGES
    V.cornerWorld = cornerWorld
    V.cornerDepth = cornerDepth
    V.NEAR_DEPTH = NEAR_DEPTH
