    V.drawArrow = drawArrow
    V.espBudget = espBudget
    V.drawEntity = drawEntity
end
end)() }
MODULES[#MODULES + 1] = { path = "src/aimlab.lua", factory = (function()
-- VEYL module: aimlab
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local RunService = V.RunService
    local UserInputService = V.UserInputService
    local Workspace = V.Workspace
    local NAMES = V.NAMES
    local Util = V.Util
    local Log = V.Log
    local Notify = V.Notify
    local Settings = V.Settings
    local Binds = V.Binds
    local Overlay = V.Overlay
    local Entities = V.Entities
    local Aim = V.Aim

    ----------------------------------------------------------------------------
    -- 11. Aim Lab (client camera only; explicit test scope)
    ----------------------------------------------------------------------------

    Aim.selected = nil
    Aim.current = nil
    Aim.running = false
    local aimBudget = { left = 0 }

    function Aim.eligible(entity)
        if entity.removed or not Entities.isAlive(entity) then
            return false
        end
        if entity.kind == "Test target" then
            return true
        elseif entity.kind == "Player" then
            return Entities.isAllowed(entity)
        end
        return Settings.get("aim.includeNpcs") == true
    end

    function Aim.eligibleList(origin)
        local list = {}
        for _, entity in pairs(Entities.byModel) do
            if Aim.eligible(entity) then
                local root = Entities.getRoot(entity)
                if root then
                    table.insert(list, { entity = entity, distance = (root.Position - origin).Magnitude })
                end
            end
        end
        table.sort(list, function(a, b)
            if a.distance == b.distance then
                return a.entity.id < b.entity.id
            end
            return a.distance < b.distance
        end)
        local entities = {}
        for index, item in ipairs(list) do
            entities[index] = item.entity
        end
        return entities
    end

    function Aim.reticle(camera)
        if Settings.get("aim.reticle") == "Mouse" then
            return UserInputService:GetMouseLocation()
        end
        return camera.ViewportSize / 2
    end

    function Aim.select(entity, silent)
        Aim.selected = entity
        if entity then
            Log.add("info", "Aim Lab target selected: " .. entity.name)
            if not silent then
                Notify.push("Aim Lab target: " .. entity.name, "info")
            end
        end
    end

    function Aim.clear(announce)
        local had = Aim.selected ~= nil
        Aim.selected = nil
        Aim.current = nil
        if announce then
            Notify.push(had and "Aim Lab target cleared." or "No Aim Lab target was selected.", "info")
        end
    end

    function Aim.cycle()
        local camera = Workspace.CurrentCamera
        if not camera then
            return
        end
        local list = Aim.eligibleList(camera.CFrame.Position)
        if #list == 0 then
            Notify.push("No eligible targets. Tag a model VEYLTestTarget, allowlist a player in Entities, or enable untagged NPCs.", "warn")
            return
        end
        local index = table.find(list, Aim.selected) or 0
        Aim.select(list[index % #list + 1])
    end

    function Aim.pick(camera, now)
        local values = Settings.values
        local origin = camera.CFrame.Position
        local partName = values["aim.targetPart"]
        local maxDistance = values["aim.maxDistance"]
        local requireLos = values["aim.requireLos"]
        aimBudget.left = 6

        local selected = Aim.selected
        if selected then
            if not Aim.eligible(selected) then
                Aim.clear(false)
                Notify.push("Selected target is no longer available (removed, dead or out of scope).", "info")
            elseif values["aim.lockSelected"] then
                local part = Entities.part(selected, partName)
                if part and (part.Position - origin).Magnitude <= maxDistance then
                    if not requireLos or Entities.visibility(selected, part, origin, aimBudget, now) == true then
                        return selected, part
                    end
                end
                return nil, nil
            end
        end

        local reticle = Aim.reticle(camera)
        local priority = values["aim.priority"]
        local best, bestPart, bestScore = nil, nil, nil
        for _, entity in pairs(Entities.byModel) do
            if Aim.eligible(entity) then
                local part = Entities.part(entity, partName)
                if part then
                    local distance = (part.Position - origin).Magnitude
                    if distance <= maxDistance then
                        local screen, inView = camera:WorldToViewportPoint(part.Position)
                        if inView and screen.Z > 0 then
                            local offset = (Vector2.new(screen.X, screen.Y) - reticle).Magnitude
                            if offset <= values["aim.fov"] then
                                local score
                                if priority == "Shortest distance" then
                                    score = distance
                                elseif priority == "Lowest health" then
                                    score = entity.humanoid.Health
                                else
                                    score = offset
                                end
                                if (bestScore == nil or score < bestScore)
                                    and (not requireLos or Entities.visibility(entity, part, origin, aimBudget, now) == true) then
                                    best, bestPart, bestScore = entity, part, score
                                end
                            end
                        end
                    end
                end
            end
        end
        return best, bestPart
    end

    function Aim.ensureVisuals()
        if not Aim.visuals then
            Aim.visuals = { fov = Overlay.new("Circle"), indicator = Overlay.new("Circle") }
        end
        return Aim.visuals
    end

    function Aim.dropVisuals()
        if Aim.visuals then
            Aim.visuals.fov:Destroy()
            Aim.visuals.indicator:Destroy()
            Aim.visuals = nil
        end
    end

    function Aim.step(deltaTime)
        local camera = Workspace.CurrentCamera
        if not camera then
            return
        end
        local values = Settings.values
        local now = os.clock()
        local target, part = Aim.pick(camera, now)
        Aim.current = target
        local visuals = Aim.ensureVisuals()
        if values["aim.showFov"] then
            visuals.fov:circle(Aim.reticle(camera), values["aim.fov"], values["color.fov"], 1, 0.8)
        else
            visuals.fov:hide()
        end
        if values["aim.showIndicator"] and part then
            local screen, inView = camera:WorldToViewportPoint(part.Position)
            if inView then
                visuals.indicator:circle(Vector2.new(screen.X, screen.Y), 7, values["color.target"], 2, 1)
            else
                visuals.indicator:hide()
            end
        else
            visuals.indicator:hide()
        end
        local active = values["aim.activation"] == "Always on" or Binds.isHeld("aimHold")
        if active and part and not UserInputService:GetFocusedTextBox() then
            local cameraCFrame = camera.CFrame
            local desired = CFrame.lookAt(cameraCFrame.Position, part.Position)
            local strength = math.clamp(values["aim.responsiveness"] / 100, 0.01, 1)
            local alpha = 1 - (1 - strength) ^ (math.min(deltaTime, 0.1) * 60)
            camera.CFrame = cameraCFrame:Lerp(desired, math.clamp(alpha, 0, 1))
        end
    end

    function Aim.start()
        if Aim.running then
            return
        end
        Overlay.ensureMode()
        Aim.running = true
        pcall(function()
            RunService:UnbindFromRenderStep(NAMES.aimStep)
        end)
        -- Runs right after the default camera update so the normal controller keeps ownership otherwise.
        RunService:BindToRenderStep(NAMES.aimStep, Enum.RenderPriority.Camera.Value + 1, Util.guardStep("Aim Lab", Aim.step, function()
            Settings.set("aim.enabled", false)
        end))
        Log.add("info", "Aim Lab armed.")
    end

    function Aim.stop()
        if Aim.running then
            pcall(function()
                RunService:UnbindFromRenderStep(NAMES.aimStep)
            end)
            Aim.running = false
        end
        Aim.dropVisuals()
        Aim.current = nil
    end

    V.aimBudget = aimBudget
end
end)() }
MODULES[#MODULES + 1] = { path = "src/world.lua", factory = (function()
-- VEYL module: world
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Lighting = V.Lighting
    local Workspace = V.Workspace
    local NAMES = V.NAMES
    local Util = V.Util
    local Log = V.Log
    local Settings = V.Settings
    local World = V.World
    local App = V.App
    local make = V.make

    ----------------------------------------------------------------------------
    -- Local FX folder (diagnostic markers, highlights). Client-created, local only.
    ----------------------------------------------------------------------------

    function App.fx()
        if App.fxFolder and App.fxFolder.Parent then
            return App.fxFolder
        end
        local folder = make("Folder", { Name = NAMES.fx })
        folder:SetAttribute(NAMES.owned, true)
        folder.Parent = Workspace
        App.fxFolder = folder
        return folder
    end

    ----------------------------------------------------------------------------
    -- 13. World: local lighting overrides with a snapshot/restore rule
    --     Rule: a property is restored only if it still holds the value VEYL
    --     wrote. If the game changed it in the meantime, the game's value stays.
    ----------------------------------------------------------------------------

    World.overrides = {}
    World.effects = {}
    World.keptChanges = 0

    local function approxEqual(a, b)
        if type(a) == "number" and type(b) == "number" then
            return math.abs(a - b) < 1e-3
        end
        if typeof(a) == "Color3" and typeof(b) == "Color3" then
            return Util.colorEquals(a, b)
        end
        return a == b
    end

    function World.write(instance, property, value)
        local map = World.overrides[instance]
        if not map then
            map = {}
            World.overrides[instance] = map
        end
        local record = map[property]
        if not record then
            record = { original = instance[property] }
            map[property] = record
        end
        instance[property] = value
        record.written = instance[property]
    end

    function World.release(instance, property)
        local map = World.overrides[instance]
        local record = map and map[property]
        if not record then
            return
        end
        map[property] = nil
        if next(map) == nil then
            World.overrides[instance] = nil
        end
        if instance.Parent == nil then
            return
        end
        if approxEqual(instance[property], record.written) then
            instance[property] = record.original
        else
            World.keptChanges += 1
            Log.add("info", "World: kept the game's newer value for " .. instance.Name .. "." .. property .. ".")
        end
    end

    function World.dropEffect(name)
        local effect = World.effects[name]
        if effect then
            effect:Destroy()
            World.effects[name] = nil
        end
    end

    function World.effect(className, name)
        local effect = World.effects[name]
        if not effect or not effect.Parent then
            effect = make(className, { Name = name })
            effect:SetAttribute(NAMES.owned, true)
            effect.Parent = Lighting
            World.effects[name] = effect
        end
        return effect
    end

    local function gameAtmosphere()
        for _, child in ipairs(Lighting:GetChildren()) do
            if child:IsA("Atmosphere") and not child:GetAttribute(NAMES.owned) then
                return child
            end
        end
        return nil
    end

    function World.apply()
        if not Settings.get("world.enabled") then
            return
        end
        local values = Settings.values
        World.write(Lighting, "Brightness", values["world.brightness"])
        World.write(Lighting, "ExposureCompensation", values["world.exposure"])
        World.write(Lighting, "GlobalShadows", values["world.shadows"])
        World.write(Lighting, "Ambient", values["world.ambient"])
        if values["world.clockOverride"] then
            World.write(Lighting, "ClockTime", values["world.clockTime"])
        else
            World.release(Lighting, "ClockTime")
        end

        if values["world.ccEnabled"] then
            local effect = World.effect("ColorCorrectionEffect", NAMES.colorCorrection)
            effect.Saturation = values["world.saturation"] / 100
            effect.Contrast = values["world.contrast"] / 100
            effect.TintColor = values["world.tint"]
            effect.Enabled = true
        else
            World.dropEffect(NAMES.colorCorrection)
        end

        if values["world.bloomEnabled"] then
            local effect = World.effect("BloomEffect", NAMES.bloom)
            effect.Intensity = values["world.bloomIntensity"] / 100
            effect.Size = values["world.bloomSize"]
            effect.Threshold = values["world.bloomThreshold"]
            effect.Enabled = true
        else
            World.dropEffect(NAMES.bloom)
        end

        local existing = gameAtmosphere()
        if values["world.atmosEnabled"] then
            if existing then
                World.dropEffect(NAMES.atmosphere)
                World.write(existing, "Density", values["world.atmosDensity"])
                World.write(existing, "Haze", values["world.atmosHaze"])
            else
                local effect = World.effect("Atmosphere", NAMES.atmosphere)
                effect.Density = values["world.atmosDensity"]
                effect.Haze = values["world.atmosHaze"]
            end
        else
            World.dropEffect(NAMES.atmosphere)
            for instance in pairs(World.overrides) do
                if instance:IsA("Atmosphere") then
                    World.release(instance, "Density")
                    World.release(instance, "Haze")
                end
            end
        end
    end

    function World.restoreAll()
        for instance, map in pairs(World.overrides) do
            for property in pairs(map) do
                World.release(instance, property)
            end
        end
        table.clear(World.overrides)
        for name in pairs(World.effects) do
            World.dropEffect(name)
        end
    end

    function World.overrideCount()
        local count = 0
        for _, map in pairs(World.overrides) do
            for _ in pairs(map) do
                count += 1
            end
        end
        for _ in pairs(World.effects) do
            count += 1
        end
        return count
    end

    V.approxEqual = approxEqual
    V.gameAtmosphere = gameAtmosphere
end
end)() }
MODULES[#MODULES + 1] = { path = "src/weapons.lua", factory = (function()
-- VEYL module: weapons
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Players = V.Players
    local RunService = V.RunService
    local ReplicatedStorage = V.ReplicatedStorage
    local StarterPack = V.StarterPack
    local Workspace = V.Workspace
    local LocalPlayer = V.LocalPlayer
    local LIMITS = V.LIMITS
    local Util = V.Util
    local Log = V.Log
    local Weapons = V.Weapons
    local Session = V.Session
    local Maid = V.Maid

    ----------------------------------------------------------------------------
    -- 14. Weapon candidate discovery (evidence only; nothing is invoked)
    ----------------------------------------------------------------------------

    Weapons.byTool = {}
    Weapons.count = 0
    Weapons.dirty = {}
    Weapons.maid = Maid.new()
    Weapons.added = Util.signal()
    Weapons.removed = Util.signal()
    Weapons.changed = Util.signal()
    Weapons.nextId = 0
    Weapons.scanToken = 0

    local RANGED_WORDS = { "gun", "rifle", "pistol", "smg", "shotgun", "sniper", "blaster", "crossbow", "launcher", "revolver", "carbine", "musket", "cannon", "laser", "bow" }
    local MELEE_WORDS = { "sword", "knife", "katana", "axe", "blade", "dagger", "spear", "hammer", "mace", "scythe", "bat" }
    local RANGED_STATS = { "ammo", "magazine", "clip", "firerate", "rpm", "spread", "recoil", "bullet", "projectile", "reload", "mag" }
    local GENERIC_STATS = { "damage", "range", "headshot", "cooldown", "velocity" }
    local MUZZLE_WORDS = { "muzzle", "firepoint", "barrel", "shootpoint", "flash" }
    local FIRE_WORDS = { "fire", "shoot", "shot", "gunshot", "reload" }

    local function matchWord(name, words)
        local lower = string.lower(name)
        for _, word in ipairs(words) do
            if string.find(lower, word, 1, true) then
                return word
            end
        end
        return nil
    end

    local function sortedKeys(map)
        local keys = {}
        for key in pairs(map) do
            table.insert(keys, key)
        end
        table.sort(keys)
        return keys
    end

    function Weapons.inScope(tool)
        return tool:IsDescendantOf(Workspace) or tool:IsDescendantOf(LocalPlayer) or tool:IsDescendantOf(StarterPack) or tool:IsDescendantOf(ReplicatedStorage)
    end

    local function toolLocation(tool)
        local character = LocalPlayer.Character
        if character and tool:IsDescendantOf(character) then
            return "Equipped"
        end
        if tool:IsDescendantOf(LocalPlayer) then
            return "Backpack"
        end
        if tool:IsDescendantOf(Workspace) then
            local ancestor = tool.Parent
            while ancestor and ancestor ~= Workspace do
                if ancestor:IsA("Model") and Players:GetPlayerFromCharacter(ancestor) then
                    return "Other player"
                end
                ancestor = ancestor.Parent
            end
            return "World"
        end
        if tool:IsDescendantOf(StarterPack) or tool:IsDescendantOf(ReplicatedStorage) then
            return "Template"
        end
        return "Other"
    end

    function Weapons.analyze(record)
        local tool = record.tool
        local evidence, unknowns = {}, {}
        local ranged, melee, generic = 0, 0, 0

        local word = matchWord(tool.Name, RANGED_WORDS)
        if word then
            ranged += 2
            table.insert(evidence, "Name contains \"" .. word .. "\" (ranged keyword)")
        end
        word = matchWord(tool.Name, MELEE_WORDS)
        if word then
            melee += 2
            table.insert(evidence, "Name contains \"" .. word .. "\" (melee keyword)")
        end

        local rangedStats, genericStats = {}, {}
        local function noteStat(name)
            local hit = matchWord(name, RANGED_STATS)
            if hit then
                rangedStats[hit] = true
                return
            end
            hit = matchWord(name, GENERIC_STATS)
            if hit then
                genericStats[hit] = true
            end
        end

        local attributes = {}
        for name, value in pairs(tool:GetAttributes()) do
            table.insert(attributes, name .. " = " .. Util.truncate(tostring(value), 24))
            noteStat(name)
        end
        table.sort(attributes)

        local values, remotes = {}, {}
        local scripts, muzzle, fireSound, fireAnimation = 0, nil, nil, nil
        local descendants = tool:GetDescendants()
        for index, descendant in ipairs(descendants) do
            if index > LIMITS.toolDescendants then
                table.insert(unknowns, "Only the first " .. LIMITS.toolDescendants .. " of " .. #descendants .. " descendants were inspected.")
                break
            end
            local className = descendant.ClassName
            if descendant:IsA("ValueBase") then
                if #values < 30 then
                    table.insert(values, descendant.Name .. " (" .. className .. ")")
                end
                noteStat(descendant.Name)
            elseif className == "RemoteEvent" or className == "RemoteFunction" or className == "UnreliableRemoteEvent" then
                table.insert(remotes, descendant.Name .. " (" .. className .. ")")
            elseif descendant:IsA("LuaSourceContainer") then
                scripts += 1
            elseif className == "Attachment" or descendant:IsA("BasePart") then
                if not muzzle and matchWord(descendant.Name, MUZZLE_WORDS) then
                    muzzle = descendant.Name
                end
            elseif className == "Sound" then
                if not fireSound and matchWord(descendant.Name, FIRE_WORDS) then
                    fireSound = descendant.Name
                end
            elseif className == "Animation" then
                if not fireAnimation and matchWord(descendant.Name, FIRE_WORDS) then
                    fireAnimation = descendant.Name
                end
            end
        end

        local rangedList = sortedKeys(rangedStats)
        if #rangedList > 0 then
            ranged += math.min(#rangedList, 4)
            table.insert(evidence, "Ranged-style stats: " .. table.concat(rangedList, ", "))
        end
        local genericList = sortedKeys(genericStats)
        if #genericList > 0 then
            generic += math.min(#genericList, 2)
            table.insert(evidence, "Combat-style stats: " .. table.concat(genericList, ", "))
        end
        if muzzle then
            ranged += 2
            table.insert(evidence, "Muzzle-like attachment/part: " .. muzzle)
        end
        if fireSound then
            ranged += 1
            table.insert(evidence, "Firing/reload sound: " .. fireSound)
        end
        if fireAnimation then
            ranged += 1
            table.insert(evidence, "Firing/reload animation: " .. fireAnimation)
        end
        local handle = tool:FindFirstChild("Handle")
        if handle then
            table.insert(evidence, "Has a Handle part")
        elseif tool.RequiresHandle then
            table.insert(unknowns, "RequiresHandle is true but no Handle exists yet (it may still be streaming in).")
        end
        if tool.ToolTip ~= "" then
            table.insert(evidence, "ToolTip: " .. Util.truncate(tool.ToolTip, 60))
        end
        if #remotes > 0 then
            table.insert(evidence, #remotes .. " remote(s) present — listed only, never invoked")
            table.insert(unknowns, "Remote arguments and server-side behavior are unknown.")
        end
        if scripts > 0 then
            table.insert(unknowns, scripts .. " script(s) define the behavior; their source cannot be read at runtime.")
        end

        local classification
        if ranged >= 3 and ranged > melee then
            classification = "Likely ranged weapon"
        elseif melee >= 2 and melee >= ranged then
            classification = "Likely melee weapon"
        elseif ranged + melee + generic >= 1 then
            classification = "Possible weapon"
        else
            classification = "Tool (purpose unknown)"
        end
        local score = math.max(ranged, melee) + generic
        record.classification = classification
        record.confidence = score >= 6 and "High" or score >= 3 and "Medium" or score >= 1 and "Low" or "None"
        record.ranged = classification == "Likely ranged weapon"
        record.evidence = evidence
        record.unknowns = unknowns
        record.attributes = attributes
        record.values = values
        record.remotes = remotes
        record.location = toolLocation(tool)
        record.path = Util.fullName(tool)
        record.name = tool.Name
        record.compat = "Unverified"
        record.analyzedAt = os.clock()
    end

    function Weapons.track(tool)
        if not Session.alive or Weapons.byTool[tool] or not tool:IsA("Tool") or not Weapons.inScope(tool) then
            return
        end
        if Weapons.count >= LIMITS.tools then
            if not Weapons.limitLogged then
                Weapons.limitLogged = true
                Log.add("warn", "Tool registry limit (" .. LIMITS.tools .. ") reached; further tools are not tracked.")
            end
            return
        end
        Weapons.nextId += 1
        local record = { tool = tool, maid = Maid.new(), id = Weapons.nextId, name = tool.Name }
        local function markDirty()
            Weapons.dirty[record] = true
        end
        record.maid:connect(tool.DescendantAdded, markDirty)
        record.maid:connect(tool.DescendantRemoving, markDirty)
        record.maid:connect(tool.AttributeChanged, markDirty)
        record.maid:connect(tool.AncestryChanged, function()
            if Weapons.inScope(tool) then
                markDirty()
            else
                Weapons.untrack(tool)
            end
        end)
        Weapons.byTool[tool] = record
        Weapons.count += 1
        local ok, err = pcall(Weapons.analyze, record)
        if not ok then
            record.classification = "Analysis failed"
            record.confidence = "None"
            record.evidence, record.unknowns, record.attributes, record.values, record.remotes = {}, { tostring(err) }, {}, {}, {}
            record.location, record.path, record.compat = toolLocation(tool), Util.fullName(tool), "Unverified"
        end
        Weapons.added:Fire(record)
    end

    function Weapons.untrack(tool)
        local record = Weapons.byTool[tool]
        if not record then
            return
        end
        Weapons.byTool[tool] = nil
        Weapons.count -= 1
        Weapons.dirty[record] = nil
        record.removed = true
        record.maid:clean()
        Weapons.removed:Fire(record)
    end

    function Weapons.scan()
        Weapons.scanToken += 1
        local token = Weapons.scanToken
        task.spawn(function()
            for _, container in ipairs({ LocalPlayer, Workspace, StarterPack, ReplicatedStorage }) do
                local descendants = container:GetDescendants()
                for index, instance in ipairs(descendants) do
                    if not Session.alive or token ~= Weapons.scanToken then
                        return
                    end
                    if instance.ClassName == "Tool" then
                        Weapons.track(instance)
                    end
                    if index % 4000 == 0 then
                        task.wait()
                    end
                end
            end
        end)
    end

    function Weapons.start()
        local function onDescendant(instance)
            if instance.ClassName == "Tool" then
                task.defer(function()
                    if Session.alive and instance.Parent then
                        Weapons.track(instance)
                    end
                end)
            end
        end
        for _, container in ipairs({ LocalPlayer, Workspace, StarterPack, ReplicatedStorage }) do
            Weapons.maid:connect(container.DescendantAdded, onDescendant)
        end
        local elapsed = 0
        Weapons.maid:connect(RunService.Heartbeat, function(deltaTime)
            elapsed += deltaTime
            if elapsed < 0.5 then
                return
            end
            elapsed = 0
            local processed = 0
            for record in pairs(Weapons.dirty) do
                Weapons.dirty[record] = nil
                if not record.removed then
                    local ok, err = pcall(Weapons.analyze, record)
                    if not ok then
                        Log.add("warn", "Tool analysis failed for " .. record.name .. ": " .. tostring(err))
                    end
                    Weapons.changed:Fire(record)
                end
                processed += 1
                if processed >= 25 then
                    break
                end
            end
        end)
        Weapons.scan()
    end

    function Weapons.rescan()
        for tool in pairs(Weapons.byTool) do
            Weapons.untrack(tool)
        end
        Weapons.limitLogged = false
        Weapons.scan()
        Log.add("info", "Tool candidates rescanned.")
    end

    function Weapons.stop()
        Weapons.scanToken += 1
        Weapons.maid:clean()
        for tool in pairs(Weapons.byTool) do
            Weapons.untrack(tool)
        end
    end

    V.RANGED_WORDS = RANGED_WORDS
    V.MELEE_WORDS = MELEE_WORDS
    V.RANGED_STATS = RANGED_STATS
    V.GENERIC_STATS = GENERIC_STATS
    V.MUZZLE_WORDS = MUZZLE_WORDS
    V.FIRE_WORDS = FIRE_WORDS
    V.matchWord = matchWord
    V.sortedKeys = sortedKeys
    V.toolLocation = toolLocation
end
end)() }
MODULES[#MODULES + 1] = { path = "src/diagnostics.lua", factory = (function()
-- VEYL module: diagnostics
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local RunService = V.RunService
    local Stats = V.Stats
    local Workspace = V.Workspace
    local LocalPlayer = V.LocalPlayer
    local VERSION = V.VERSION
    local LIMITS = V.LIMITS
    local Log = V.Log
    local Cap = V.Cap
    local Settings = V.Settings
    local Entities = V.Entities
    local Weapons = V.Weapons
    local Diag = V.Diag
    local App = V.App
    local Maid = V.Maid
    local T = V.T
    local make = V.make

    ----------------------------------------------------------------------------
    -- 15. Diagnostics (client-visible observations only)
    ----------------------------------------------------------------------------

    Diag.history = {}
    Diag.markers = {}
    Diag.jumps = 0
    Diag.spikes = 0
    Diag.frameMs = 0

    function Diag.fps()
        return Diag.frameMs > 0 and math.floor(1000 / Diag.frameMs + 0.5) or 0
    end

    function Diag.mark(from, to)
        if not Settings.get("diag.markers") then
            return
        end
        local folder = App.fx()
        local function ball(position, color)
            local part = make("Part", {
                Name = "VEYLMarker",
                Anchored = true,
                CanCollide = false,
                CanQuery = false,
                CanTouch = false,
                CastShadow = false,
                Material = Enum.Material.Neon,
                Shape = Enum.PartType.Ball,
                Size = Vector3.new(0.8, 0.8, 0.8),
                Color = color,
                Transparency = 0.2,
                Position = position,
            })
            part.Parent = folder
            return part
        end
        local entry = { ball(from, T.warn), ball(to, T.bad) }
        table.insert(Diag.markers, entry)
        while #Diag.markers > LIMITS.markers do
            for _, part in ipairs(table.remove(Diag.markers, 1)) do
                part:Destroy()
            end
        end
        task.delay(10, function()
            local index = table.find(Diag.markers, entry)
            if index then
                table.remove(Diag.markers, index)
                for _, part in ipairs(entry) do
                    part:Destroy()
                end
            end
        end)
    end

    function Diag.clearMarkers()
        for _, entry in ipairs(Diag.markers) do
            for _, part in ipairs(entry) do
                part:Destroy()
            end
        end
        table.clear(Diag.markers)
    end

    function Diag.sample()
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root or not root:IsA("BasePart") then
            Diag.previous = nil
            return
        end
        local now = os.clock()
        local sample = { t = now, position = root.Position, velocity = root.AssemblyLinearVelocity }
        local previous = Diag.previous
        if previous and now - previous.t < 1 then
            local elapsed = now - previous.t
            local moved = (sample.position - previous.position).Magnitude
            local expected = math.max(previous.velocity.Magnitude, sample.velocity.Magnitude) * elapsed + 2
            local excess = moved - expected
            if excess > Settings.get("diag.posThreshold") then
                Diag.jumps += 1
                Log.add("warn", string.format("Position discontinuity observed: %.1f st in %.2f s (%.1f st beyond the velocity estimate). Client-side observation only; it does not prove server desync.", moved, elapsed, excess))
                Diag.mark(previous.position, sample.position)
            end
            local deltaVelocity = (sample.velocity - previous.velocity).Magnitude
            if deltaVelocity > Settings.get("diag.velThreshold") then
                Diag.spikes += 1
                Log.add("info", string.format("Velocity change observed: %.0f st/s within %.2f s.", deltaVelocity, elapsed))
            end
        end
        Diag.previous = sample
        table.insert(Diag.history, sample)
        if #Diag.history > LIMITS.history then
            table.remove(Diag.history, 1)
        end
    end

    function Diag.ping()
        local okNetwork, seconds = pcall(function()
            return LocalPlayer:GetNetworkPing()
        end)
        local network = (okNetwork and type(seconds) == "number") and (math.floor(seconds * 1000 + 0.5) .. " ms") or "Unavailable"
        local okData, data = pcall(function()
            local networkStats = Stats:FindFirstChild("Network")
            local serverStats = networkStats and networkStats:FindFirstChild("ServerStatsItem")
            local item = serverStats and serverStats:FindFirstChild("Data Ping")
            return item and item:GetValueString()
        end)
        return network, (okData and data) or "Unavailable"
    end

    function Diag.resetCounters()
        Diag.jumps, Diag.spikes = 0, 0
        table.clear(Diag.history)
        Diag.previous = nil
        Diag.clearMarkers()
    end

    function Diag.start()
        if Diag.maid then
            return
        end
        local maid = Maid.new()
        Diag.maid = maid
        local elapsed = 0
        maid:connect(RunService.Heartbeat, function(deltaTime)
            elapsed += deltaTime
            if elapsed >= 0.1 then
                elapsed = 0
                local ok, err = pcall(Diag.sample)
                if not ok and not Diag.sampleFailed then
                    Diag.sampleFailed = true
                    Log.add("warn", "Diagnostics sample failed: " .. tostring(err))
                end
            end
        end)
        maid:connect(RunService.RenderStepped, function(deltaTime)
            local ms = deltaTime * 1000
            Diag.frameMs = Diag.frameMs == 0 and ms or (Diag.frameMs * 0.9 + ms * 0.1)
        end)
        maid:connect(LocalPlayer.CharacterAdded, function()
            Diag.previous = nil
            Log.add("info", "Local character respawned; observations continue on the new character.")
        end)
    end

    function Diag.stop()
        if Diag.maid then
            Diag.maid:clean()
            Diag.maid = nil
        end
        Diag.clearMarkers()
        Diag.previous = nil
        Diag.frameMs = 0
    end

    function Diag.summary()
        local lines = {}
        local function add(line)
            table.insert(lines, line)
        end
        local network, data = Diag.ping()
        add("VEYL Control " .. VERSION .. " diagnostic summary (" .. os.date("%Y-%m-%d %H:%M:%S") .. ")")
        add("Runtime: " .. Cap.modeText())
        for _, row in ipairs(Cap.report) do
            add("  " .. row.name .. ": " .. row.status .. " — " .. row.detail)
        end
        add("Place: " .. game.PlaceId .. "  ·  Studio: " .. tostring(Cap.studio))
        add("FPS (estimate): " .. Diag.fps() .. "  ·  network ping: " .. network .. "  ·  data ping: " .. data)
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and root:IsA("BasePart") then
            local p = root.Position
            add(string.format("Position: %.1f, %.1f, %.1f  ·  speed %.1f st/s", p.X, p.Y, p.Z, root.AssemblyLinearVelocity.Magnitude))
        end
        local camera = Workspace.CurrentCamera
        if camera then
            add("Camera: " .. camera.CameraType.Name .. "  ·  FOV " .. math.floor(camera.FieldOfView + 0.5))
        end
        add(string.format("Entities: %d  ·  tool candidates: %d  ·  position jumps: %d  ·  velocity spikes: %d", Entities.count, Weapons.count, Diag.jumps, Diag.spikes))
        add("Recent log:")
        for index = 1, math.min(20, #Log.entries) do
            add("  " .. Log.format(Log.entries[index]))
        end
        return table.concat(lines, "\n")
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/music.lua", factory = (function()
-- VEYL module: music
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local SoundService = V.SoundService
    local MarketplaceService = V.MarketplaceService
    local ContentProvider = V.ContentProvider
    local NAMES = V.NAMES
    local LIMITS = V.LIMITS
    local Util = V.Util
    local Log = V.Log
    local Notify = V.Notify
    local Settings = V.Settings
    local Persist = V.Persist
    local Music = V.Music
    local Session = V.Session
    local Maid = V.Maid
    local T = V.T
    local make = V.make

    ----------------------------------------------------------------------------
    -- 17. Music Hub: Roblox audio assets via Sound; provider links are bookmarks
    ----------------------------------------------------------------------------

    Music.queue = {}
    Music.bookmarks = {}
    Music.current = nil
    Music.sound = nil
    Music.paused = false
    Music.loadState = "none"
    Music.status = "Idle"
    Music.statusColor = T.muted
    Music.changed = Util.signal()
    Music.bookmarksChanged = Util.signal()
    Music.infoQueue = {}
    Music.infoRunning = false

    local PROVIDERS = {
        ["open.spotify.com"] = "Spotify",
        ["spotify.link"] = "Spotify",
        ["music.youtube.com"] = "YouTube Music",
        ["www.youtube.com"] = "YouTube",
        ["youtube.com"] = "YouTube",
        ["m.youtube.com"] = "YouTube",
        ["youtu.be"] = "YouTube",
    }
    local CREDENTIAL_HINTS = { "token=", "access_token", "refresh_token", "code=", "client_secret", "password", "apikey", "api_key" }

    function Music.setStatus(message, color)
        Music.status = message
        Music.statusColor = color or T.muted
    end

    function Music.isPlaying()
        local sound = Music.sound
        return sound ~= nil and sound.Parent ~= nil and sound.IsPlaying and not Music.paused
    end

    function Music.normalize(raw)
        local value = Util.trim(raw)
        local id = string.match(value, "^rbxassetid://(%d+)$") or string.match(value, "^(%d+)$")
        if not id then
            return nil, "Enter a numeric asset ID (1234567890) or rbxassetid://1234567890."
        end
        id = string.gsub(id, "^0+", "")
        if id == "" or #id > 16 then
            return nil, "That asset ID is out of range."
        end
        return id
    end

    function Music.indexOf(track)
        return track and table.find(Music.queue, track) or nil
    end

    function Music.requestInfo(track)
        table.insert(Music.infoQueue, track)
        if Music.infoRunning then
            return
        end
        Music.infoRunning = true
        task.spawn(function()
            while Session.alive and #Music.infoQueue > 0 do
                local item = table.remove(Music.infoQueue, 1)
                if table.find(Music.queue, item) then
                    local ok, info = pcall(function()
                        return MarketplaceService:GetProductInfo(tonumber(item.id), Enum.InfoType.Asset)
                    end)
                    if ok and type(info) == "table" then
                        if info.AssetTypeId == 3 then
                            item.title = Util.truncate(tostring(info.Name or item.title), 60)
                            item.creator = type(info.Creator) == "table" and info.Creator.Name or nil
                            item.info = "ok"
                        else
                            item.info = "notAudio"
                            item.warning = "Asset type " .. tostring(info.AssetTypeId) .. " is not audio"
                        end
                    else
                        item.info = "unavailable"
                    end
                    Music.changed:Fire()
                    task.wait(0.25)
                end
            end
            Music.infoRunning = false
        end)
    end

    function Music.add(raw)
        local id, err = Music.normalize(raw)
        if not id then
            Notify.push(err, "warn")
            return false
        end
        for _, track in ipairs(Music.queue) do
            if track.id == id then
                Notify.push("Asset " .. id .. " is already in the queue.", "warn")
                return false
            end
        end
        if #Music.queue >= LIMITS.queue then
            Notify.push("The queue is limited to " .. LIMITS.queue .. " tracks.", "warn")
            return false
        end
        local track = { id = id, title = "Audio " .. id, favorite = false, info = "pending" }
        table.insert(Music.queue, track)
        Music.requestInfo(track)
        Log.add("info", "Queued audio asset " .. id .. ".")
        Music.changed:Fire()
        Persist.schedule()
        return true
    end

    function Music.applyVolume(sound)
        sound = typeof(sound) == "Instance" and sound or Music.sound
        if sound then
            sound.Volume = Settings.get("music.muted") and 0 or Settings.get("music.volume") / 100
        end
    end

    function Music.stop(keepStatus)
        if Music.trackMaid then
            Music.trackMaid:clean()
            Music.trackMaid = nil
        end
        Music.sound = nil
        Music.paused = false
        Music.loadState = "none"
        if not keepStatus then
            Music.setStatus("Stopped", T.muted)
            Music.changed:Fire()
        end
    end

    function Music.play(track)
        if not track then
            if #Music.queue == 0 then
                Notify.push("The queue is empty. Add a Roblox audio asset ID first.", "warn")
                return
            end
            track = Music.queue[1]
        end
        Music.stop(true)
        Music.current = track
        local maid = Maid.new()
        Music.trackMaid = maid
        local sound = make("Sound", { Name = NAMES.sound, SoundId = "rbxassetid://" .. track.id, Looped = false })
        sound:SetAttribute(NAMES.owned, true)
        Music.applyVolume(sound)
        sound.Parent = SoundService
        maid:give(sound)
        Music.sound = sound
        Music.loadState = "loading"
        Music.setStatus("Loading asset " .. track.id .. "…", T.muted)
        maid:connect(sound.Loaded, function()
            if Music.sound == sound then
                Music.loadState = "loaded"
                Music.setStatus(Music.paused and "Paused" or "Playing", T.ok)
            end
        end)
        maid:connect(sound.Ended, function()
            if Music.sound == sound then
                Music.onEnded()
            end
        end)
        task.spawn(function()
            local ok, err = pcall(function()
                ContentProvider:PreloadAsync({ sound }, function(_, status)
                    if Music.sound == sound and status == Enum.AssetFetchStatus.Failure then
                        Music.loadState = "failed"
                        Music.setStatus("Load failed: private, removed, not audio, or not permitted here", T.bad)
                        Notify.push("Audio " .. track.id .. " failed to load. It may be private, removed, or not permitted in this experience.", "warn")
                        Music.changed:Fire()
                    end
                end)
            end)
            if not ok and Music.sound == sound then
                Log.add("warn", "Audio load check failed: " .. tostring(err))
            end
        end)
        local ok, err = pcall(function()
            sound:Play()
        end)
        if not ok then
            Music.loadState = "failed"
            Music.setStatus("Playback failed", T.bad)
            Notify.push("Playback failed for " .. track.id .. ": " .. tostring(err), "error")
        end
        maid:delay(10, function()
            if Music.sound == sound and not sound.IsLoaded and Music.loadState == "loading" then
                Music.setStatus("Still loading — may be unavailable or not permitted", T.warn)
            end
        end)
        Music.changed:Fire()
    end

    function Music.togglePlay()
        local sound = Music.sound
        if sound and sound.Parent then
            if Music.paused then
                sound:Resume()
                Music.paused = false
                Music.setStatus(Music.loadState == "loaded" and "Playing" or "Loading…", Music.loadState == "loaded" and T.ok or T.muted)
            elseif sound.IsPlaying then
                sound:Pause()
                Music.paused = true
                Music.setStatus("Paused", T.muted)
            else
                sound:Play()
            end
            Music.changed:Fire()
            return
        end
        Music.play(Music.indexOf(Music.current) and Music.current or Music.queue[1])
    end

    function Music.next(automatic)
        local count = #Music.queue
        if count == 0 then
            if not automatic then
                Notify.push("The queue is empty.", "warn")
            end
            Music.stop()
            return
        end
        local index = Music.indexOf(Music.current) or 0
        local nextIndex
        if Settings.get("music.shuffle") and count > 1 then
            if index == 0 then
                nextIndex = math.random(1, count)
            else
                nextIndex = math.random(1, count - 1)
                if nextIndex >= index then
                    nextIndex += 1
                end
            end
        elseif index < count then
            nextIndex = index + 1
        elseif not automatic or Settings.get("music.repeatMode") == "All" then
            nextIndex = 1
        else
            Music.stop(true)
            Music.setStatus("Queue finished", T.muted)
            Music.changed:Fire()
            return
        end
        Music.play(Music.queue[nextIndex])
    end

    function Music.previous()
        local sound = Music.sound
        if sound and sound.IsLoaded and sound.TimePosition > 3 then
            sound.TimePosition = 0
            return
        end
        local count = #Music.queue
        if count == 0 then
            Notify.push("The queue is empty.", "warn")
            return
        end
        local index = Music.indexOf(Music.current) or 1
        Music.play(Music.queue[index > 1 and index - 1 or count])
    end

    function Music.onEnded()
        if Settings.get("music.repeatMode") == "One" and Music.sound then
            Music.sound.TimePosition = 0
            Music.sound:Play()
            return
        end
        Music.next(true)
    end

    function Music.seek(fraction)
        local sound = Music.sound
        if not (sound and sound.IsLoaded and sound.TimeLength > 0) then
            Notify.push("Seeking becomes available after the asset has loaded.", "info")
            return
        end
        sound.TimePosition = math.clamp(fraction, 0, 1) * sound.TimeLength
    end

    function Music.remove(track)
        local index = Music.indexOf(track)
        if not index then
            return
        end
        if track == Music.current then
            Music.stop()
            Music.current = nil
        end
        table.remove(Music.queue, index)
        Music.changed:Fire()
        Persist.schedule()
    end

    function Music.move(track, delta)
        local index = Music.indexOf(track)
        local target = index and index + delta
        if not target or target < 1 or target > #Music.queue then
            return
        end
        Music.queue[index], Music.queue[target] = Music.queue[target], Music.queue[index]
        Music.changed:Fire()
        Persist.schedule()
    end

    function Music.toggleFavorite(track)
        track.favorite = not track.favorite
        Music.changed:Fire()
        Persist.schedule()
    end

    function Music.clear()
        Music.stop()
        Music.current = nil
        table.clear(Music.queue)
        Music.changed:Fire()
        Persist.schedule()
    end

    function Music.validateUrl(raw)
        local url = Util.trim(raw)
        if url == "" then
            return nil, "Paste a Spotify or YouTube Music https:// link."
        end
        if #url > 300 then
            return nil, "That link is longer than 300 characters."
        end
        if string.find(url, "[%s%c]") then
            return nil, "Links cannot contain spaces or control characters."
        end
        local host = string.match(url, "^https://([^/%?#]+)")
        if not host then
            return nil, "Only https:// links are accepted."
        end
        host = string.lower(host)
        if string.find(host, "@", 1, true) or string.find(host, ":", 1, true) then
            return nil, "Links with embedded credentials or ports are not accepted."
        end
        local provider = PROVIDERS[host]
        if not provider then
            return nil, "Supported hosts: open.spotify.com, spotify.link, music.youtube.com, youtube.com, youtu.be."
        end
        local lower = string.lower(url)
        for _, hint in ipairs(CREDENTIAL_HINTS) do
            if string.find(lower, hint, 1, true) then
                return nil, "This link looks like it contains a credential, so it was not saved."
            end
        end
        return url, provider
    end

    function Music.addBookmark(raw)
        raw = Util.trim(raw)
        local label, rest = string.match(raw, "^(.-)%s*|%s*(%S+)$")
        local url, provider = Music.validateUrl(rest or raw)
        if not url then
            Notify.push(provider, "warn")
            return false
        end
        for _, bookmark in ipairs(Music.bookmarks) do
            if bookmark.url == url then
                Notify.push("That link is already bookmarked.", "warn")
                return false
            end
        end
        if #Music.bookmarks >= LIMITS.bookmarks then
            Notify.push("Bookmarks are limited to " .. LIMITS.bookmarks .. ".", "warn")
            return false
        end
        label = Util.truncate(Util.trim(label or ""), 40)
        table.insert(Music.bookmarks, { label = label ~= "" and label or provider, url = url, provider = provider })
        Music.bookmarksChanged:Fire()
        Persist.schedule()
        Notify.push("Bookmark saved. It opens outside Roblox; it does not play here.", "ok")
        return true
    end

    function Music.removeBookmark(bookmark)
        local index = table.find(Music.bookmarks, bookmark)
        if index then
            table.remove(Music.bookmarks, index)
            Music.bookmarksChanged:Fire()
            Persist.schedule()
        end
    end

    function Music.serialize()
        local queue, bookmarks = {}, {}
        for _, track in ipairs(Music.queue) do
            table.insert(queue, { id = track.id, favorite = track.favorite })
        end
        for _, bookmark in ipairs(Music.bookmarks) do
            table.insert(bookmarks, { label = bookmark.label, url = bookmark.url })
        end
        return { queue = queue, bookmarks = bookmarks }
    end

    function Music.loadTable(data)
        if type(data) ~= "table" then
            return
        end
        if type(data.queue) == "table" then
            local seen = {}
            for _, track in ipairs(Music.queue) do
                seen[track.id] = true
            end
            for _, item in ipairs(data.queue) do
                if type(item) == "table" and #Music.queue < LIMITS.queue then
                    local id = Music.normalize(tostring(item.id or ""))
                    if id and not seen[id] then
                        seen[id] = true
                        local track = { id = id, title = "Audio " .. id, favorite = item.favorite == true, info = "pending" }
                        table.insert(Music.queue, track)
                        Music.requestInfo(track)
                    end
                end
            end
        end
        if type(data.bookmarks) == "table" then
            for _, item in ipairs(data.bookmarks) do
                if type(item) == "table" and #Music.bookmarks < LIMITS.bookmarks then
                    local url, provider = Music.validateUrl(tostring(item.url or ""))
                    if url then
                        local label = type(item.label) == "string" and Util.truncate(Util.trim(item.label), 40) or ""
                        table.insert(Music.bookmarks, { label = label ~= "" and label or provider, url = url, provider = provider })
                    end
                end
            end
        end
        Music.changed:Fire()
        Music.bookmarksChanged:Fire()
    end

    V.PROVIDERS = PROVIDERS
    V.CREDENTIAL_HINTS = CREDENTIAL_HINTS
end
end)() }
MODULES[#MODULES + 1] = { path = "src/features.lua", factory = (function()
-- VEYL module: features
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local TeleportService = V.TeleportService
    local LocalPlayer = V.LocalPlayer
    local Util = V.Util
    local Log = V.Log
    local Notify = V.Notify
    local Cap = V.Cap
    local Settings = V.Settings
    local Binds = V.Binds
    local UI = V.UI
    local Popup = V.Popup
    local Overlay = V.Overlay
    local ESP = V.ESP
    local Aim = V.Aim
    local World = V.World
    local Diag = V.Diag
    local Music = V.Music
    local Rejoin = V.Rejoin
    local Features = V.Features
    local Session = V.Session
    local T = V.T

    ----------------------------------------------------------------------------
    -- 16. Rejoin (documented TeleportService APIs only)
    ----------------------------------------------------------------------------

    Rejoin.busy = false
    Rejoin.state = "Idle"
    Rejoin.token = 0

    function Rejoin.request(mode)
        if Rejoin.busy then
            Notify.push("A rejoin request is already in progress.", "warn")
            return
        end
        if Cap.studio then
            Notify.push("Teleports do not work in Studio. Test rejoin in a published experience.", "warn")
            return
        end
        if mode == "server" and (type(game.JobId) ~= "string" or game.JobId == "") then
            Notify.push("This server has no JobId to rejoin.", "warn")
            return
        end
        Rejoin.busy = true
        Rejoin.token += 1
        local token = Rejoin.token
        Rejoin.state = mode == "server" and "Requesting this server…" or "Requesting matchmaking…"
        UI.flashStatus("● " .. Rejoin.state, T.warn, 6)
        Log.add("info", "Rejoin requested (" .. (mode == "server" and "current server" or "matchmaking") .. ").")
        local ok, err = pcall(function()
            if mode == "server" then
                TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
            else
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end
        end)
        if not ok then
            Rejoin.busy = false
            Rejoin.state = "Failed: " .. Util.truncate(tostring(err), 60)
            Notify.push("Rejoin request failed: " .. tostring(err), "error")
            return
        end
        task.delay(30, function()
            if Session.alive and Rejoin.busy and token == Rejoin.token then
                Rejoin.busy = false
                Rejoin.state = "No teleport progress after 30 s"
                Notify.push("Rejoin did not start within 30 seconds; the request may have been rejected.", "warn")
            end
        end)
    end

    function Rejoin.onFailed(player, result, message)
        if player ~= LocalPlayer then
            return
        end
        Rejoin.busy = false
        Rejoin.state = "Failed: " .. tostring(result and result.Name or result)
        Notify.push("Teleport failed (" .. tostring(result and result.Name or result) .. "): " .. tostring(message), "error")
    end

    ----------------------------------------------------------------------------
    -- Feature-level controls (emergency stop, resets)
    ----------------------------------------------------------------------------

    local FEATURE_PREFIXES = {
        ["Aim Lab"] = "aim.",
        ["Visuals"] = "esp.",
        ["Colors"] = "color.",
        ["World"] = "world.",
        ["Music"] = "music.",
        ["Diagnostics"] = "diag.",
        ["Interface"] = "ui.",
    }
    Features.resetTargets = { "Aim Lab", "Visuals", "Colors", "World", "Music", "Diagnostics", "Interface" }

    function Features.emergencyStop(source)
        Binds.cancelCapture()
        Popup.close()
        UI.dragging = nil
        Settings.set("aim.enabled", false)
        Settings.set("esp.enabled", false)
        Settings.set("world.enabled", false)
        Settings.set("diag.enabled", false)
        -- Direct calls as well, in case a listener failed earlier.
        pcall(Aim.stop)
        pcall(ESP.stop)
        pcall(World.restoreAll)
        pcall(Diag.stop)
        Aim.clear(false)
        Music.stop()
        Overlay.clearAll()
        UI.flashStatus("● Stopped", T.bad, 4)
        Log.add("warn", "Emergency stop (" .. tostring(source) .. "): Aim Lab, ESP, world overrides, music and diagnostics stopped.")
        Notify.push("Emergency stop: every feature is off and temporary visuals were removed.", "ok")
    end

    function Features.resetFeature(name)
        local prefix = FEATURE_PREFIXES[name]
        if not prefix then
            return
        end
        Settings.resetPrefix(prefix)
        if name == "Aim Lab" then
            Aim.clear(false)
        end
        Notify.push(name .. " settings restored to defaults.", "ok")
    end

    function Features.restoreDefaults()
        Settings.resetPrefix(nil)
        Aim.clear(false)
        Notify.push("All settings restored to defaults. Keybinds are unchanged.", "ok")
    end

    V.FEATURE_PREFIXES = FEATURE_PREFIXES
end
end)() }
MODULES[#MODULES + 1] = { path = "src/pages/shared.lua", factory = (function()
-- VEYL module: pages/shared
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Settings = V.Settings
    local Entities = V.Entities
    local styledButton = V.styledButton

    ----------------------------------------------------------------------------
    -- 7. Tabs and panels
    ----------------------------------------------------------------------------

    local Pages = {}

    local function rowButton(frame, label, xFromRight, width, style, maid)
        local button = styledButton(frame, label, style, maid)
        button.AnchorPoint = Vector2.new(1, 0.5)
        button.Position = UDim2.new(1, -xFromRight, 0.5, 0)
        button.Size = UDim2.fromOffset(width, 20)
        return button
    end

    local function kindColorUi(kind)
        if kind == "Player" then
            return Settings.get("color.player")
        elseif kind == "Test target" then
            return Settings.get("color.testTarget")
        end
        return Settings.get("color.npc")
    end

    local function aimIneligibleReason(entity)
        if not Entities.isAlive(entity) then
            return "This entity is dead or has no Humanoid."
        end
        if entity.kind == "Player" and not Entities.isAllowed(entity) then
            return "Allowlist this player first (Allow button)."
        end
        if entity.kind == "NPC" and not Settings.get("aim.includeNpcs") then
            return "Enable Aim Lab › Include untagged NPCs, or tag the model VEYLTestTarget."
        end
        return nil
    end

    V.Pages = Pages
    V.rowButton = rowButton
    V.kindColorUi = kindColorUi
    V.aimIneligibleReason = aimIneligibleReason
end
end)() }
MODULES[#MODULES + 1] = { path = "src/pages/main.lua", factory = (function()
-- VEYL module: pages/main
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Cap = V.Cap
    local Settings = V.Settings
    local Binds = V.Binds
    local Persist = V.Persist
    local UI = V.UI
    local Overlay = V.Overlay
    local Entities = V.Entities
    local ESP = V.ESP
    local Aim = V.Aim
    local World = V.World
    local Weapons = V.Weapons
    local Diag = V.Diag
    local Music = V.Music
    local Features = V.Features
    local Root = V.Root
    local T = V.T
    local Pages = V.Pages

    -- MAIN ---------------------------------------------------------------------
    function Pages.main()
        local page = UI.page("Main")
        local status = UI.section(page, "left", "Status")
        local rows = {
            runtime = UI.info(status, { label = "Runtime", desc = "Detected runtime. See Misc › Runtime capabilities for details." }),
            aim = UI.info(status, { label = "Aim Lab", desc = "Camera aim testing for eligible test targets." }),
            target = UI.info(status, { label = "Selected target", desc = "Explicit Aim Lab selection (C cycles, V clears by default)." }),
            esp = UI.info(status, { label = "ESP", desc = "Client-side overlays for eligible entities." }),
            world = UI.info(status, { label = "World overrides", desc = "Local lighting overrides currently applied." }),
            music = UI.info(status, { label = "Music", desc = "Music Hub playback state." }),
            entities = UI.info(status, { label = "Entities tracked", desc = "Live character models in Workspace." }),
            weapons = UI.info(status, { label = "Tool candidates", desc = "Tools discovered automatically; see Weapons." }),
            diag = UI.info(status, { label = "Diagnostics", desc = "Frame-rate estimate and ping." }),
            config = UI.info(status, { label = "Configuration", desc = "Where settings are stored." }),
        }

        local quick = UI.section(page, "right", "Quick toggles")
        UI.toggle(quick, { key = "aim.enabled", label = "Aim Lab", desc = "Arm camera aim testing for eligible targets." })
        UI.toggle(quick, { key = "esp.enabled", label = "ESP overlays", desc = "Boxes, labels, health bars and tracers for eligible entities." })
        UI.toggle(quick, { key = "world.enabled", label = "World overrides", desc = "Apply the local lighting settings from the World tab." })
        UI.toggle(quick, { key = "diag.enabled", label = "Diagnostics sampling", desc = "Sample local position and velocity at 10 Hz." })
        UI.toggle(quick, { key = "diag.markers", label = "Discontinuity markers", desc = "Place temporary local markers where a position jump was observed." })
        UI.toggle(quick, { key = "music.muted", label = "Mute music", desc = "Silence the Music Hub without stopping it." })

        local actions = UI.section(page, "right", "Actions")
        UI.buttons(actions, {
            { text = "Cycle target", callback = Aim.cycle },
            { text = "Clear target", callback = function()
                Aim.clear(true)
            end },
        }, "Cycle through eligible Aim Lab targets or clear the selection.")
        UI.button(actions, {
            text = "Restore defaults…",
            desc = "Reset every setting to its default after confirmation. Keybinds are kept.",
            callback = function()
                UI.confirm("Restore defaults", "Reset all settings to their defaults? Active features will be switched off. Keybinds are kept.", "Restore", Features.restoreDefaults)
            end,
        })
        UI.button(actions, {
            text = "EMERGENCY STOP",
            style = "danger",
            desc = "Stop every feature loop, restore lighting, stop audio and remove temporary visuals.",
            callback = function()
                Features.emergencyStop("button")
            end,
        })

        local hotkeys = UI.section(page, "right", "Hotkeys")
        local hotkeyNote = UI.note(hotkeys, "")
        local function renderHotkeys()
            local lines = {}
            for _, action in ipairs(Binds.actions) do
                table.insert(lines, string.format("%-10s %s", Binds.display(Binds.map[action.id]), action.label))
            end
            hotkeyNote.set(table.concat(lines, "\n"), T.muted)
        end
        renderHotkeys()
        Root:give(Binds.changed:Connect(renderHotkeys))

        page.onUpdate = function()
            rows.runtime.set(Cap.modeText(), Cap.executorAware and T.cyan or T.muted)
            if Settings.get("aim.enabled") then
                local activation = Settings.get("aim.activation") == "Always on" and "always on" or ("hold " .. Binds.display(Binds.map.aimHold))
                rows.aim.set((Aim.current and ("Tracking " .. Aim.current.name) or "Armed") .. " · " .. activation, T.ok)
            else
                rows.aim.set("Off", T.muted)
            end
            rows.target.set(Aim.selected and Aim.selected.name or "None (auto within FOV)", Aim.selected and T.text or T.muted)
            if Settings.get("esp.enabled") then
                rows.esp.set(string.format("On · %s · %d drawn", tostring(Overlay.mode), ESP.drawn), T.ok)
            else
                rows.esp.set("Off", T.muted)
            end
            rows.world.set(Settings.get("world.enabled") and string.format("On · %d overrides", World.overrideCount()) or "Off", Settings.get("world.enabled") and T.ok or T.muted)
            rows.music.set(Music.status, Music.statusColor)
            local players, npcs, targets = 0, 0, 0
            for _, entity in pairs(Entities.byModel) do
                if entity.kind == "Player" then
                    players += 1
                elseif entity.kind == "NPC" then
                    npcs += 1
                else
                    targets += 1
                end
            end
            rows.entities.set(string.format("%d (%d players · %d NPC · %d test)%s", Entities.count, players, npcs, targets, Entities.scanning and " · scanning" or ""))
            local ranged = 0
            for _, record in pairs(Weapons.byTool) do
                if record.ranged then
                    ranged += 1
                end
            end
            rows.weapons.set(string.format("%d found · %d likely ranged", Weapons.count, ranged))
            if Diag.maid then
                local network = Diag.ping()
                rows.diag.set(string.format("%d FPS (est.) · ping %s", Diag.fps(), network), T.text)
            else
                rows.diag.set("Off", T.muted)
            end
            rows.config.set(Persist.status, Persist.available and T.text or T.warn)
        end
        page.updateInterval = 0.5
    end
end
end)() }
