MODULES[#MODULES + 1] = { path = "src/pages/entities.lua", factory = (function()
-- VEYL module: pages/entities
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Workspace = V.Workspace
    local LIMITS = V.LIMITS
    local Util = V.Util
    local Notify = V.Notify
    local UI = V.UI
    local Entities = V.Entities
    local ESP = V.ESP
    local Aim = V.Aim
    local Root = V.Root
    local T = V.T
    local text = V.text
    local Pages = V.Pages
    local rowButton = V.rowButton
    local kindColorUi = V.kindColorUi
    local aimIneligibleReason = V.aimIneligibleReason

    -- ENTITIES -----------------------------------------------------------------
    function Pages.entities()
        local page = UI.page("Entities")
        local registry = UI.section(page, "left", "Live registry")
        local filterText, filterKind = "", "All"
        local inspected
        local list
        local dirty = true
        local countRow

        local function matches(entity)
            if filterKind == "Allowed player" then
                if entity.kind ~= "Player" or not Entities.isAllowed(entity) then
                    return false
                end
            elseif filterKind ~= "All" and entity.kind ~= filterKind then
                return false
            end
            return filterText == "" or string.find(string.lower(entity.name), filterText, 1, true) ~= nil
        end

        local function buildRow(entity)
            return function(frame, maid)
                local nameLabel = text(frame, { Position = UDim2.fromOffset(8, 3), Size = UDim2.new(1, -170, 0, 16), Font = T.fontMedium, Text = entity.name })
                local detail = text(frame, { Position = UDim2.fromOffset(8, 19), Size = UDim2.new(1, -170, 0, 14), TextSize = 10, TextColor3 = T.muted, Text = "" })
                local inspect = rowButton(frame, "Inspect", 4, 52, "default", maid)
                local aim = rowButton(frame, "Aim", 60, 44, "default", maid)
                local allow
                if entity.player then
                    allow = rowButton(frame, "Allow", 108, 52, "default", maid)
                    maid:connect(allow.Activated, function()
                        Entities.setAllowed(entity, not Entities.isAllowed(entity))
                        dirty = true
                    end)
                end
                maid:connect(inspect.Activated, function()
                    inspected = entity
                    UI.updatePage(true)
                end)
                maid:connect(aim.Activated, function()
                    local reason = aimIneligibleReason(entity)
                    if reason then
                        Notify.push(reason, "warn")
                    else
                        Aim.select(entity)
                    end
                end)
                return function(origin)
                    nameLabel.Text = entity.name .. (Aim.selected == entity and "  ◎" or "")
                    nameLabel.TextColor3 = kindColorUi(entity.kind)
                    local root = Entities.getRoot(entity)
                    local distance = root and (root.Position - origin).Magnitude or nil
                    local humanoid = entity.humanoid
                    local health = humanoid and string.format("%d/%d HP", math.floor(humanoid.Health + 0.5), math.floor(humanoid.MaxHealth + 0.5)) or "no HP"
                    local aimText = Aim.eligible(entity) and "✓" or "—"
                    local espText = ESP.eligible(entity) and "✓" or "—"
                    detail.Text = string.format("%s · %s · %s · A:%s E:%s", entity.kind, distance and (math.floor(distance + 0.5) .. " st") or "no root", health, aimText, espText)
                    if allow then
                        allow.Text = Entities.isAllowed(entity) and "Revoke" or "Allow"
                    end
                    frame.LayoutOrder = distance and math.floor(distance) or 1e6
                end
            end
        end

        UI.filterBox(registry, "Search by name…", function(value)
            filterText = value
            dirty = true
            UI.updatePage(true)
        end)
        UI.dropdown(registry, {
            label = "Type",
            desc = "Filter by classification.",
            options = function()
                return { "All", "Test target", "Player", "Allowed player", "NPC" }
            end,
            get = function()
                return filterKind
            end,
            set = function(value)
                filterKind = value
                dirty = true
                UI.updatePage(true)
            end,
        })
        countRow = UI.info(registry, { label = "Showing", desc = "Rows are capped at " .. LIMITS.entityRows .. " and sorted by distance from the camera." })
        list = UI.list(registry, "No live entities match.")

        local function sync()
            dirty = false
            local shown, total = 0, 0
            for _, entity in pairs(Entities.byModel) do
                local want = matches(entity)
                if want then
                    total += 1
                end
                if want and shown < LIMITS.entityRows then
                    shown += 1
                    if not list.get(entity) then
                        list.add(entity, 38, buildRow(entity))
                    end
                elseif list.get(entity) then
                    list.remove(entity)
                end
            end
            for entity in pairs(list.rows) do
                if entity.removed then
                    list.remove(entity)
                end
            end
            countRow.set(string.format("%d of %d match%s", shown, total, Entities.scanning and " · scanning" or ""))
        end

        local inspector = UI.section(page, "right", "Inspector")
        local fields = {
            name = UI.info(inspector, { label = "Name", desc = "Display name, or VEYLTargetName attribute for test targets." }),
            kind = UI.info(inspector, { label = "Classification", desc = "Test target (tag), Player (GetPlayerFromCharacter) or NPC." }),
            distance = UI.info(inspector, { label = "Distance (camera)", desc = "Measured from the current camera position, in studs." }),
            health = UI.info(inspector, { label = "Health", desc = "Humanoid Health / MaxHealth as replicated to this client." }),
            state = UI.info(inspector, { label = "Humanoid state", desc = "Humanoid:GetState() as seen by this client." }),
            position = UI.info(inspector, { label = "Root position", desc = "World position of the root part." }),
            screen = UI.info(inspector, { label = "Screen", desc = "Whether the root projects inside the viewport." }),
            eligible = UI.info(inspector, { label = "Aim / ESP scope", desc = "Eligibility under the current filters." }),
        }
        local pathNote = UI.note(inspector, "Select Inspect on a row to see details.")
        UI.buttons(inspector, {
            { text = "Select for Aim Lab", style = "primary", callback = function()
                if not inspected or inspected.removed then
                    Notify.push("Inspect an entity first.", "warn")
                    return
                end
                local reason = aimIneligibleReason(inspected)
                if reason then
                    Notify.push(reason, "warn")
                else
                    Aim.select(inspected)
                end
            end },
            { text = "Toggle allowlist", callback = function()
                if not inspected or inspected.removed or not inspected.player then
                    Notify.push("Inspect a player first.", "warn")
                    return
                end
                Entities.setAllowed(inspected, not Entities.isAllowed(inspected))
            end },
        }, "Act on the inspected entity.")

        local allowSection = UI.section(page, "right", "Session allowlist")
        local allowRow = UI.info(allowSection, { label = "Allowlisted players", desc = "Session only; never saved to disk." })
        UI.note(allowSection, "Live players remain excluded from Aim Lab and ESP until you explicitly allowlist them for this session. Use this with consenting test participants; the allowlist is local to this VEYL session only.")
        UI.button(allowSection, {
            text = "Clear allowlist",
            desc = "Remove every player from the session allowlist.",
            callback = function()
                table.clear(Entities.allow)
                for _, entity in pairs(Entities.byModel) do
                    if entity.player then
                        Entities.changed:Fire(entity)
                    end
                end
                Notify.push("Allowlist cleared.", "ok")
            end,
        })
        UI.button(allowSection, { text = "Rebuild registry", desc = "Drop and rediscover every live entity.", callback = Entities.rebuild })

        Root:give(Entities.added:Connect(function()
            dirty = true
        end))
        Root:give(Entities.changed:Connect(function()
            dirty = true
        end))
        Root:give(Entities.removed:Connect(function(entity)
            list.remove(entity)
            if inspected == entity then
                inspected = nil
            end
            dirty = true
        end))

        page.onShow = function()
            dirty = true
        end
        page.updateInterval = 0.5
        page.onUpdate = function()
            if dirty then
                sync()
            end
            local camera = Workspace.CurrentCamera
            local origin = camera and camera.CFrame.Position or Vector3.zero
            for _, entry in pairs(list.rows) do
                entry.update(origin)
            end
            local allowCount = 0
            for _ in pairs(Entities.allow) do
                allowCount += 1
            end
            allowRow.set(tostring(allowCount))
            if inspected and not inspected.removed then
                local entity = inspected
                local root = Entities.getRoot(entity)
                local humanoid = entity.humanoid
                fields.name.set(entity.name)
                fields.kind.set(entity.kind, kindColorUi(entity.kind))
                fields.distance.set(root and (math.floor((root.Position - origin).Magnitude + 0.5) .. " st") or "No root part")
                fields.health.set(humanoid and string.format("%.0f / %.0f", humanoid.Health, humanoid.MaxHealth) or "Unavailable")
                local okState, state = pcall(function()
                    return humanoid:GetState().Name
                end)
                fields.state.set(okState and state or "Unavailable")
                fields.position.set(root and string.format("%.1f, %.1f, %.1f", root.Position.X, root.Position.Y, root.Position.Z) or "Unavailable")
                if root and camera then
                    local _, inView = camera:WorldToViewportPoint(root.Position)
                    fields.screen.set(inView and "On screen" or "Off screen")
                else
                    fields.screen.set("Unavailable")
                end
                fields.eligible.set((Aim.eligible(entity) and "Aim ✓" or "Aim ✗") .. "  ·  " .. (ESP.eligible(entity) and "ESP ✓" or "ESP ✗"))
                pathNote.set("Path: " .. Util.fullName(entity.model), T.muted)
            else
                for _, field in pairs(fields) do
                    field.set("—", T.dim)
                end
                pathNote.set("Select Inspect on a row to see details.", T.dim)
            end
        end
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/pages/weapons.lua", factory = (function()
-- VEYL module: pages/weapons
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local LIMITS = V.LIMITS
    local UI = V.UI
    local Weapons = V.Weapons
    local Root = V.Root
    local T = V.T
    local text = V.text
    local Pages = V.Pages
    local rowButton = V.rowButton

    -- WEAPONS ------------------------------------------------------------------
    function Pages.weapons()
        local page = UI.page("Weapons")
        local candidates = UI.section(page, "left", "Tool candidates")
        local filterText, filterLocation = "", "All"
        local inspected
        local dirty = true
        local list
        local countRow

        local function matches(record)
            if filterLocation ~= "All" and record.location ~= filterLocation then
                return false
            end
            return filterText == "" or string.find(string.lower(record.name), filterText, 1, true) ~= nil
        end

        local function buildRow(record)
            return function(frame, maid)
                local nameLabel = text(frame, { Position = UDim2.fromOffset(8, 3), Size = UDim2.new(1, -72, 0, 16), Font = T.fontMedium, Text = record.name })
                local detail = text(frame, { Position = UDim2.fromOffset(8, 19), Size = UDim2.new(1, -72, 0, 14), TextSize = 10, TextColor3 = T.muted, Text = "" })
                local inspect = rowButton(frame, "Inspect", 4, 56, "default", maid)
                maid:connect(inspect.Activated, function()
                    inspected = record
                    UI.updatePage(true)
                end)
                return function()
                    nameLabel.Text = record.name
                    nameLabel.TextColor3 = record.ranged and T.cyan or T.text
                    detail.Text = string.format("%s · %s · %s confidence", record.location or "?", record.classification or "Analyzing", record.confidence or "?")
                    frame.LayoutOrder = (record.ranged and 0 or 1000) + record.id % 1000
                end
            end
        end

        UI.filterBox(candidates, "Search tools…", function(value)
            filterText = value
            dirty = true
            UI.updatePage(true)
        end)
        UI.dropdown(candidates, {
            label = "Location",
            desc = "Filter by where the tool currently is.",
            options = function()
                return { "All", "Equipped", "Backpack", "World", "Other player", "Template", "Other" }
            end,
            get = function()
                return filterLocation
            end,
            set = function(value)
                filterLocation = value
                dirty = true
                UI.updatePage(true)
            end,
        })
        countRow = UI.info(candidates, { label = "Showing", desc = "Tools from your Backpack, character, Workspace, StarterPack and ReplicatedStorage." })
        list = UI.list(candidates, "No tools discovered yet.")

        local function sync()
            dirty = false
            local shown, total = 0, 0
            for _, record in pairs(Weapons.byTool) do
                local want = matches(record)
                if want then
                    total += 1
                end
                if want and shown < LIMITS.toolRows then
                    shown += 1
                    if not list.get(record) then
                        list.add(record, 38, buildRow(record))
                    end
                elseif list.get(record) then
                    list.remove(record)
                end
            end
            for record in pairs(list.rows) do
                if record.removed then
                    list.remove(record)
                end
            end
            for _, entry in pairs(list.rows) do
                entry.update()
            end
            countRow.set(string.format("%d of %d match", shown, total))
        end

        local inspector = UI.section(page, "right", "Inspector")
        local fields = {
            name = UI.info(inspector, { label = "Name", desc = "Tool.Name" }),
            location = UI.info(inspector, { label = "Location", desc = "Equipped, Backpack, World, Other player, Template or Other." }),
            classification = UI.info(inspector, { label = "Classification", desc = "Heuristic from names, values, attachments, sounds and animations." }),
            confidence = UI.info(inspector, { label = "Confidence", desc = "Strength of the evidence, not proof." }),
            compat = UI.info(inspector, { label = "Compatibility", desc = "Verified only after a real verification test. None exists, so every tool is Unverified." }),
        }
        local pathNote = UI.note(inspector, "Select Inspect on a row to see evidence.")
        local evidenceNote = UI.note(inspector, "")
        local unknownNote = UI.note(inspector, "", T.warn)
        local detailNote = UI.note(inspector, "")

        local about = UI.section(page, "right", "How discovery works")
        UI.note(about, "Discovery is automatic and event-driven: tools are re-analysed when their descendants or attributes change, never by rescanning every frame.")
        UI.note(about, "Finding a Tool does not prove it is a gun, and finding a remote does not reveal its arguments. VEYL lists remotes but never invokes them, and script source cannot be read at runtime.", T.warn)
        UI.button(about, { text = "Rescan tools", desc = "Drop and rediscover every tool candidate.", callback = Weapons.rescan })

        Root:give(Weapons.added:Connect(function()
            dirty = true
        end))
        Root:give(Weapons.changed:Connect(function(record)
            local entry = list.get(record)
            if entry then
                entry.update()
            end
            dirty = true
        end))
        Root:give(Weapons.removed:Connect(function(record)
            list.remove(record)
            if inspected == record then
                inspected = nil
            end
            dirty = true
        end))

        page.onShow = function()
            dirty = true
        end
        page.updateInterval = 0.5
        page.onUpdate = function()
            if dirty then
                sync()
            end
            local record = inspected
            if record and not record.removed then
                fields.name.set(record.name)
                fields.location.set(record.location or "?")
                fields.classification.set(record.classification or "Analyzing", record.ranged and T.cyan or T.text)
                fields.confidence.set(record.confidence or "?")
                fields.compat.set("Unverified", T.warn)
                pathNote.set("Path: " .. (record.path or "?"), T.muted)
                evidenceNote.set("Evidence:\n• " .. (#record.evidence > 0 and table.concat(record.evidence, "\n• ") or "none found"), T.text)
                local unknowns = table.clone(record.unknowns)
                table.insert(unknowns, "No verified fire interface; VEYL never invokes tool remotes. Aim Lab only turns the camera.")
                unknownNote.set("Unknowns:\n• " .. table.concat(unknowns, "\n• "), T.warn)
                local details = {}
                if #record.attributes > 0 then
                    table.insert(details, "Attributes: " .. table.concat(record.attributes, ", "))
                end
                if #record.values > 0 then
                    table.insert(details, "Value objects: " .. table.concat(record.values, ", "))
                end
                if #record.remotes > 0 then
                    table.insert(details, "Remotes (not invoked): " .. table.concat(record.remotes, ", "))
                end
                detailNote.set(#details > 0 and table.concat(details, "\n") or "No attributes, value objects or remotes.", T.muted)
            else
                for _, field in pairs(fields) do
                    field.set("—", T.dim)
                end
                pathNote.set("Select Inspect on a row to see evidence.", T.dim)
                evidenceNote.set("", T.dim)
                unknownNote.set("", T.dim)
                detailNote.set("", T.dim)
            end
        end
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/pages/music.lua", factory = (function()
-- VEYL module: pages/music
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Util = V.Util
    local Settings = V.Settings
    local UI = V.UI
    local Music = V.Music
    local Features = V.Features
    local Root = V.Root
    local T = V.T
    local make = V.make
    local corner = V.corner
    local text = V.text
    local isPress = V.isPress
    local Pages = V.Pages
    local rowButton = V.rowButton

    -- MUSIC --------------------------------------------------------------------
    function Pages.music()
        local page = UI.page("Music")
        local now = UI.section(page, "left", "Now playing")
        local titleRow = UI.info(now, { label = "Track", desc = "Title from Roblox asset info when available; otherwise the asset ID." })
        local assetRow = UI.info(now, { label = "Asset", desc = "Canonical asset ID and creator." })
        local statusRow = UI.info(now, { label = "Status", desc = "Loading, permission and playback state reported by Roblox." })

        local progressRow, _ = UI.row(now, 22, { label = "Progress", desc = "Click to seek once the asset has loaded." })
        local bar = make("TextButton", { Position = UDim2.new(0, 4, 0.5, -3), Size = UDim2.new(1, -96, 0, 6), BackgroundColor3 = T.line, BorderSizePixel = 0, Text = "", AutoButtonColor = false }, progressRow)
        corner(bar, 3)
        local barFill = make("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = T.cyan, BorderSizePixel = 0 }, bar)
        corner(barFill, 3)
        local timeLabel = text(progressRow, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -4, 0, 0), Size = UDim2.fromOffset(84, 22), Text = "0:00 / 0:00", TextSize = 11, Font = T.mono, TextXAlignment = Enum.TextXAlignment.Right })
        Root:connect(bar.InputBegan, function(input)
            if isPress(input) then
                Music.seek((input.Position.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1))
            end
        end)

        local transport = UI.buttons(now, {
            { text = "‹‹ Prev", callback = Music.previous },
            { text = "▶ Play", style = "primary", callback = Music.togglePlay },
            { text = "■ Stop", callback = function()
                Music.stop()
            end },
            { text = "Next ››", callback = function()
                Music.next(false)
            end },
        }, "Previous restarts the track if more than 3 s have played.")
        UI.slider(now, { key = "music.volume", label = "Volume", suffix = "%", desc = "Session volume. Mute overrides it." })
        UI.toggle(now, { key = "music.muted", label = "Mute", desc = "Set the Sound volume to zero." })
        UI.toggle(now, { key = "music.shuffle", label = "Shuffle", desc = "Pick a random different track when advancing." })
        UI.dropdown(now, { key = "music.repeatMode", label = "Repeat", desc = "Off, repeat one track, or repeat the whole queue." })
        UI.button(now, {
            text = "Reset player settings",
            desc = "Restore volume, mute, shuffle, repeat and the favorites filter.",
            callback = function()
                Features.resetFeature("Music")
            end,
        })

        local add = UI.section(page, "left", "Add a Roblox audio asset")
        UI.input(add, {
            label = "Audio asset ID",
            placeholder = "1234567890 or rbxassetid://1234567890",
            buttonText = "Add",
            desc = "Only audio this experience is permitted to use will load.",
            onSubmit = Music.add,
        })
        UI.note(add, "Playback uses a Roblox Sound in SoundService. Private, removed or unpermitted assets fail to load and the failure is shown above. Nothing is downloaded or re-hosted.")

        local queueSection = UI.section(page, "right", "Queue")
        local queueFilter = ""
        UI.filterBox(queueSection, "Search queue…", function(value)
            queueFilter = value
            Music.changed:Fire()
        end)
        UI.toggle(queueSection, { key = "music.favoritesOnly", label = "Favorites only", desc = "Show only starred tracks." })
        local queueCount = UI.info(queueSection, { label = "Tracks", desc = "Session queue (saved with the config when a file API exists)." })
        local queueList = UI.list(queueSection, "The queue is empty.")
        UI.button(queueSection, {
            text = "Clear queue…",
            style = "danger",
            desc = "Stop playback and remove every track.",
            callback = function()
                UI.confirm("Clear queue", "Remove all " .. #Music.queue .. " tracks from the queue?", "Clear", Music.clear)
            end,
        })

        local function buildTrackRow(track)
            return function(frame, maid)
                local title = text(frame, { Position = UDim2.fromOffset(8, 3), Size = UDim2.new(1, -150, 0, 16), Font = T.fontMedium, Text = track.title })
                local detail = text(frame, { Position = UDim2.fromOffset(8, 19), Size = UDim2.new(1, -150, 0, 14), TextSize = 10, TextColor3 = T.muted, Text = "" })
                local remove = rowButton(frame, "×", 4, 22, "danger", maid)
                local down = rowButton(frame, "↓", 30, 22, "default", maid)
                local up = rowButton(frame, "↑", 56, 22, "default", maid)
                local star = rowButton(frame, "☆", 82, 22, "default", maid)
                local play = rowButton(frame, "▶", 108, 34, "primary", maid)
                maid:connect(play.Activated, function()
                    Music.play(track)
                end)
                maid:connect(star.Activated, function()
                    Music.toggleFavorite(track)
                end)
                maid:connect(up.Activated, function()
                    Music.move(track, -1)
                end)
                maid:connect(down.Activated, function()
                    Music.move(track, 1)
                end)
                maid:connect(remove.Activated, function()
                    Music.remove(track)
                end)
                return function(index)
                    local playing = Music.current == track
                    title.Text = (playing and "♪ " or "") .. track.title
                    title.TextColor3 = playing and T.cyan or T.text
                    local info = "rbxassetid://" .. track.id
                    if track.creator then
                        info = info .. " · " .. track.creator
                    end
                    if track.info == "notAudio" then
                        info = info .. " · " .. (track.warning or "not audio")
                    elseif track.info == "unavailable" then
                        info = info .. " · asset info unavailable"
                    end
                    detail.Text = info
                    detail.TextColor3 = track.info == "notAudio" and T.warn or T.muted
                    star.Text = track.favorite and "★" or "☆"
                    star.TextColor3 = track.favorite and T.warn or T.text
                    frame.LayoutOrder = index
                    local visible = (not Settings.get("music.favoritesOnly") or track.favorite)
                        and (queueFilter == "" or string.find(string.lower(track.title .. " " .. track.id), queueFilter, 1, true) ~= nil)
                    frame.Visible = visible
                    return visible
                end
            end
        end

        local function syncQueue()
            local present = {}
            local visibleCount = 0
            for index, track in ipairs(Music.queue) do
                present[track] = true
                local entry = queueList.get(track) or queueList.add(track, 38, buildTrackRow(track))
                if entry and entry.update(index) then
                    visibleCount += 1
                end
            end
            for track in pairs(queueList.rows) do
                if not present[track] then
                    queueList.remove(track)
                end
            end
            queueCount.set(string.format("%d of %d shown", visibleCount, #Music.queue))
        end
        Root:give(Music.changed:Connect(syncQueue))
        Root:give(Settings.on("music.favoritesOnly", syncQueue))

        local providers = UI.section(page, "right", "Provider bookmarks")
        UI.input(providers, {
            label = "Bookmark URL",
            placeholder = "Label | https://open.spotify.com/…",
            buttonText = "Save",
            desc = "Spotify, YouTube Music or YouTube links. Optional label before a | character.",
            onSubmit = Music.addBookmark,
        })
        local bookmarkList = UI.list(providers, "No bookmarks saved.")
        UI.note(providers, "Bookmarks are links only. Roblox cannot play Spotify or YouTube Music, and VEYL does not open, stream, scrape or proxy them. Copy a link to open it in your browser.", T.warn)

        local function syncBookmarks()
            local present = {}
            for index, bookmark in ipairs(Music.bookmarks) do
                present[bookmark] = true
                local entry = bookmarkList.get(bookmark) or bookmarkList.add(bookmark, 38, function(frame, maid)
                    text(frame, { Position = UDim2.fromOffset(8, 3), Size = UDim2.new(1, -96, 0, 16), Font = T.fontMedium, Text = bookmark.label .. "  ·  " .. bookmark.provider })
                    text(frame, { Position = UDim2.fromOffset(8, 19), Size = UDim2.new(1, -96, 0, 14), TextSize = 10, TextColor3 = T.muted, Text = bookmark.url })
                    local remove = rowButton(frame, "×", 4, 22, "danger", maid)
                    local copy = rowButton(frame, "Copy link", 30, 58, "default", maid)
                    maid:connect(copy.Activated, function()
                        UI.copy("Bookmark link", bookmark.url)
                    end)
                    maid:connect(remove.Activated, function()
                        Music.removeBookmark(bookmark)
                    end)
                    return function(order)
                        frame.LayoutOrder = order
                    end
                end)
                if entry then
                    entry.update(index)
                end
            end
            for bookmark in pairs(bookmarkList.rows) do
                if not present[bookmark] then
                    bookmarkList.remove(bookmark)
                end
            end
        end
        Root:give(Music.bookmarksChanged:Connect(syncBookmarks))
        syncQueue()
        syncBookmarks()

        local playButton = transport.buttons[2]
        page.updateInterval = 0.2
        page.onUpdate = function()
            local track = Music.current
            titleRow.set(track and track.title or "No track", track and T.text or T.muted)
            assetRow.set(track and (track.id .. (track.creator and (" · " .. track.creator) or "")) or "—", T.muted)
            statusRow.set(Music.status, Music.statusColor)
            local sound = Music.sound
            if sound and sound.Parent and sound.IsLoaded and sound.TimeLength > 0 then
                barFill.Size = UDim2.fromScale(math.clamp(sound.TimePosition / sound.TimeLength, 0, 1), 1)
                timeLabel.Text = Util.formatTime(sound.TimePosition) .. " / " .. Util.formatTime(sound.TimeLength)
            else
                barFill.Size = UDim2.fromScale(0, 1)
                timeLabel.Text = sound and "loading…" or "0:00 / 0:00"
            end
            playButton.Text = Music.isPlaying() and "❚❚ Pause" or "▶ Play"
        end
    end
end
end)() }
MODULES[#MODULES + 1] = { path = "src/pages/diagnostics.lua", factory = (function()
-- VEYL module: pages/diagnostics
-- Loaded by loader.lua (or dist/VEYL.lua). Receives the shared context table V.
return function(V)
    local Workspace = V.Workspace
    local LocalPlayer = V.LocalPlayer
    local LIMITS = V.LIMITS
    local Log = V.Log
    local UI = V.UI
    local Diag = V.Diag
    local T = V.T
    local make = V.make
    local corner = V.corner
    local padding = V.padding
    local text = V.text
    local Pages = V.Pages

    -- DIAGNOSTICS --------------------------------------------------------------
    function Pages.diagnostics()
        local page = UI.page("Diagnostics")
        local live = UI.section(page, "left", "Live client observations")
        local rows = {
            fps = UI.info(live, { label = "Frame rate", desc = "Estimate from a smoothed RenderStepped frame time." }),
            frame = UI.info(live, { label = "Frame time", desc = "Smoothed frame time in milliseconds." }),
            position = UI.info(live, { label = "Position", desc = "Local HumanoidRootPart position, studs." }),
            velocity = UI.info(live, { label = "Velocity", desc = "AssemblyLinearVelocity magnitude, studs per second." }),
            walk = UI.info(live, { label = "WalkSpeed", desc = "Local Humanoid.WalkSpeed." }),
            state = UI.info(live, { label = "Humanoid state", desc = "Local Humanoid:GetState()." }),
            camera = UI.info(live, { label = "Camera", desc = "CameraType and FieldOfView." }),
            subject = UI.info(live, { label = "Camera subject", desc = "Camera.CameraSubject." }),
            camDistance = UI.info(live, { label = "Camera ↔ character", desc = "Distance from the camera to your root part, studs." }),
            ping = UI.info(live, { label = "Network ping", desc = "Player:GetNetworkPing() in milliseconds, if available." }),
            dataPing = UI.info(live, { label = "Data ping (Stats)", desc = "Stats › Network › ServerStatsItem › Data Ping, if readable." }),
            history = UI.info(live, { label = "History", desc = "Bounded 10 Hz sample buffer." }),
        }

        local detection = UI.section(page, "right", "Discontinuity detection")
        UI.toggle(detection, { key = "diag.enabled", label = "Enable sampling", desc = "Sample local position and velocity at 10 Hz." })
        UI.toggle(detection, { key = "diag.markers", label = "Place markers", desc = "Temporary local markers (removed after 10 s, max " .. LIMITS.markers .. ")." })
        UI.slider(detection, { key = "diag.posThreshold", label = "Position jump threshold", suffix = " st", desc = "Distance beyond what velocity explains before an event is logged." })
        UI.slider(detection, { key = "diag.velThreshold", label = "Velocity change threshold", suffix = " st/s", desc = "Velocity change within one sample before an event is logged." })
        local jumpsRow = UI.info(detection, { label = "Position jumps", desc = "Observed since the last reset." })
        local spikesRow = UI.info(detection, { label = "Velocity spikes", desc = "Observed since the last reset." })
        UI.button(detection, { text = "Reset counters and markers", desc = "Clear history, counters and markers.", callback = Diag.resetCounters })
        UI.note(detection, "These are client-side observations. A local position jump does not prove a server-side desync; Studio Network Simulator is not used.", T.warn)

        local logSection = UI.section(page, "right", "Event log")
        local logHolder = make("ScrollingFrame", {
            BackgroundColor3 = T.field,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 200),
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 4,
            ScrollBarImageColor3 = T.line,
            LayoutOrder = logSection.nextOrder(),
        }, logSection.frame)
        corner(logHolder, 4)
        table.insert(logSection.rows, { frame = logHolder, follow = true, text = "" })
        local logText = text(logHolder, {
            Size = UDim2.fromScale(1, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            Font = T.mono,
            TextSize = 11,
            TextColor3 = T.muted,
            TextWrapped = true,
            TextTruncate = Enum.TextTruncate.None,
            TextYAlignment = Enum.TextYAlignment.Top,
            Text = "",
        })
        padding(logText, 6, 6, 4, 4)
        UI.buttons(logSection, {
            { text = "Clear log", callback = Log.clear },
            { text = "Copy log", callback = function()
                local lines = {}
                for _, entry in ipairs(Log.entries) do
                    table.insert(lines, Log.format(entry))
                end
                UI.copy("Event log", #lines > 0 and table.concat(lines, "\n") or "(empty)")
            end },
        }, "Latest first; capped at " .. LIMITS.logs .. " entries.")
        local shownVersion = -1

        page.updateInterval = 0.25
        page.onUpdate = function()
            if Diag.maid then
                rows.fps.set(Diag.fps() .. " FPS (estimate)")
                rows.frame.set(string.format("%.1f ms", Diag.frameMs))
            else
                rows.fps.set("Sampling off", T.muted)
                rows.frame.set("—", T.muted)
            end
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if root and root:IsA("BasePart") then
                local p = root.Position
                rows.position.set(string.format("%.1f, %.1f, %.1f", p.X, p.Y, p.Z))
                rows.velocity.set(string.format("%.1f st/s", root.AssemblyLinearVelocity.Magnitude))
            else
                rows.position.set("No character", T.muted)
                rows.velocity.set("—", T.muted)
            end
            if humanoid then
                rows.walk.set(string.format("%.1f", humanoid.WalkSpeed))
                rows.state.set(humanoid:GetState().Name)
            else
                rows.walk.set("—", T.muted)
                rows.state.set("—", T.muted)
            end
            local camera = Workspace.CurrentCamera
            if camera then
                rows.camera.set(camera.CameraType.Name .. " · FOV " .. math.floor(camera.FieldOfView + 0.5))
                local subject = camera.CameraSubject
                rows.subject.set(subject and (subject.Name .. " (" .. subject.ClassName .. ")") or "None")
                rows.camDistance.set((root and root:IsA("BasePart")) and string.format("%.1f st", (camera.CFrame.Position - root.Position).Magnitude) or "—")
            else
                rows.camera.set("No camera", T.bad)
            end
            local network, data = Diag.ping()
            rows.ping.set(network)
            rows.dataPing.set(data)
            rows.history.set(#Diag.history .. " / " .. LIMITS.history .. " samples")
            jumpsRow.set(tostring(Diag.jumps), Diag.jumps > 0 and T.warn or T.text)
            spikesRow.set(tostring(Diag.spikes))
            if shownVersion ~= Log.version then
                shownVersion = Log.version
                local lines = {}
                for index = 1, math.min(LIMITS.logView, #Log.entries) do
                    table.insert(lines, Log.format(Log.entries[index]))
                end
                logText.Text = #lines > 0 and table.concat(lines, "\n") or "(log is empty)"
            end
        end
    end
end
end)() }
